const DATA={};

function add(lang,rows){
  if(rows.length!==PRACTICAL_GUIDE_IDS.length) throw new Error(`Practical guide count: ${lang}`);
  DATA[lang]=Object.fromEntries(rows.map((row,index)=>{
    if(row.length!==5) throw new Error(`Practical guide fields: ${lang}/${PRACTICAL_GUIDE_IDS[index]}`);
    const [title,overview,decision,check,caution]=row;
    return [PRACTICAL_GUIDE_IDS[index],{title,overview,decision,check,caution}];
  }));
}

add('en',[
  ['Hero & Squad Formations','Use two heroes in front and three in back. A full five-hero Tank, Aircraft, or Missile squad earns the same-type bonus.','Tank: Murphy and Williams front; Kimberly, Stetmann, Marshall back. Aircraft: Carlie and Lucius front; DVA, Morrison, Schuyler back. Missile: Adam and McGregor front; Tesla, Fiona, Swift back. Air beats Tank, Tank beats Missile, Missile beats Air.','Keep defenders in the visible front row and damage dealers behind them. Compare real squad power and buffs before changing type; a much weaker counter squad can still lose.','Do not break your strongest developed squad just to copy a formation. Build one complete core five before funding a second squad.'],
  ["Drone Chips & Components","Drone Chips, Drone Components, and Drone Parts are different items. Match each chip set to the hero type it supports.","The four UR chip slots: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Craft your first UR set in this order. Firestorm at 2 and 5 stars hits more targets.","Level one complete core set at a balanced pace. Confirm the chip role, hero type, star preview, and material name in the upgrade screen.","Do not spend parts or components as if they were chips, and do not star a second-squad set before the core set works together."],
  ['UR Gear & Blueprints','Bring level 40 gold Legendary gear to the core five first; concentrated upgrades beat thin investment across many heroes.','For Kimberly, DVA, and Tesla prioritize Railgun/Cannon, then Chip. For Murphy, Williams, Lucius, and Carlie prioritize Armor, then Radar. Legendary Blueprints unlock gear stars; Mythic Blueprints matter later.','Use the gear preview to confirm the next star requirement and time major upgrades with an active scoring event when useful.','Blueprint needs change by star and version. Do not trust fixed totals or spread expensive materials across every squad.'],
  ['Store Buy Priorities','Each shop uses its own currency. Protect the purchases that solve a bottleneck; F2P players should avoid clearing shelves without a plan.','VIP: weekly stamina, selected speedups, and UR shards only when affordable. Honor: save mainly for Legendary Gear Blueprints. Alliance: always reserve 8h/24h shields for Saturday RZSN policy, then UR shards, Drone Parts, and speedups as needed. Campaign: resource boxes—especially gold near HQ30—Legendary Campaign chests, Drone Parts, or universal EW shards according to stock.','Read the currency icon, remaining stock, and reset timer before buying. Prices and inventory can differ by server and game version.','Never spend shield reserves on convenience items. No listed price here is guaranteed.'],
  ['Waterfall Troop Training','Keep several Barracks at useful tier milestones so troops can be promoted through a chain during a scoring window.','Milestones: T6 at Barracks 17, T7 at 20, T8 at 24, T9 at 27, and T10 at 30 plus Unit X research. With Barracks 17/20/24/27, train T6 during the week, then promote T6 → T7 → T8 → T9 when Friday’s live rules reward promotions.','Before starting, verify the current VS/event score, queues, promotion time, and Drill Ground capacity. Keep room for the whole chain.','Promotion scoring is not always four times and rules can change. Follow the live event screen, not an old calculator.'],
  ["General's Trial","Choose the highest unlocked difficulty in General's Trial. Later enemies may be too strong to defeat alone, but the alliance can help.","If an enemy is too strong, ask for help in alliance chat. Stronger RZSN members can start a rally or join yours to defeat it together. Include the difficulty and enemy level.","Check the event UI for mode, stamina cost, attempts, rewards, and reset because variants exist. Coordinate in alliance chat rather than assuming every trial has an R5 schedule.","Do not drop to a lower difficulty just because one enemy is too strong solo. Ask for rally support and check the live event rules."],
  ['Zombie Siege','Zombie Siege runs for 20 waves in common versions. A shield does not stop event zombies, so wall defense and reinforcement decide survival.','Station a proper strong defensive squad on the wall. Stronger members should reinforce weaker bases before later waves; ask R4/R5 which event level the alliance will open.','Watch incoming waves, wall squads, reinforcement capacity, and elimination state. Once eliminated, your base receives no further attacks in that run.','Failure rules differ between sources and versions. Do not rely on an “only one failure” claim—read the live event rules.'],
  ["Marshal's Guard",'This is a coordinated 30-minute damage event with five armored tank bosses and three-minute rallies in common versions.','Stay near the hive to reduce march time. Send your strongest suitable squad to rallies; a weaker member may start if that produces the best join order. Donate to the drill platform and follow officer priorities, with up to five phases per target set.','Confirm the live event time and rally plan. RZSN often uses 20:00 CET / 16:00 ST, but the announced schedule is authoritative.','Do not hardcode the usual hour or launch off-plan rallies that split the alliance’s damage.'],
  ['Rally & Combat Fundamentals','A rally is not evaluated the same way in every mode. The leader choice, buffs, counters, and target authorization all matter.','In Season PvE infection fights, the rally leader’s resistance can cover lower-resistance participants. In PvP, compare actual squad strength, type counter, hero/gear buffs, and march composition. Only an authorized leader starts stronghold rallies.','Before marching, inspect the target, leader, participant order, counter cycle, and active buffs. On Saturday keep the required shield and never hit allied or unauthorized targets.','Resistance does not replace PvP strength. Joining the wrong leader or dropping a shield can harm the whole alliance.'],
  ['Desert Storm','Win through assigned groups, fast communication, and sustained scoring—not random solo teleports. Reserves should reflect real availability.','Protect or contest hospitals first when the map supports them, then hold steady point sources such as refineries, Science Hub/Info Center, and the Nuclear Silo when it opens. Teleport in staggered groups and move to the called focus.','Confirm your role, partner group, reserve status, and current map objectives before entry; layouts and objective names can vary.','Do not port alone into an unsupported lane or chase kills while high-value structures are unattended.'],
  ['Alliance Tech & Donation Priorities','Alliance research donations go to alliance technology—not your personal Tech Center. Donate to the R4/R5 highlighted recommendation.','Use the preferred research when its 20% bonus is active and collect contribution points. Early alliances usually value Economy/Development; a mature RZSN gains more from Combat ATK, DEF, and HP. Fund Territory only for an upcoming need.','Check the highlighted research, bonus state, remaining donation cost, and current officer call before donating.','Gold donations are not compulsory when your resources are strained. Avoid scattering donations across unapproved branches.'],
  ['Minister & Capitol Buffs','Receive the title or buff before pressing Start. Buffs normally do not shorten research or construction already in progress.','Ask for Secretary of Science before long research and Co-Builder before construction. With two Tech Centers, prepare both queues before the title window. Co-operative Research and Research Now are Engineer skills; use their active timers deliberately.','Verify the title is active on your profile, then start the action. Check each skill description and timer in-game before using Research Now.','Do not add percentage labels as simple arithmetic or assume a late title applies retroactively.']
]);

add('de',[
  ['Helden- & Squad-Formationen','Stelle zwei Helden nach vorn und drei nach hinten. Fünf Helden desselben Typs geben den vollständigen Tank-, Aircraft- oder Missile-Bonus.','Tank: Murphy und Williams vorn; Kimberly, Stetmann, Marshall hinten. Aircraft: Carlie und Lucius vorn; DVA, Morrison, Schuyler hinten. Missile: Adam und McGregor vorn; Tesla, Fiona, Swift hinten. Air schlägt Tank, Tank schlägt Missile, Missile schlägt Air.','Die Verteidiger müssen sichtbar in der Frontreihe stehen. Vergleiche echte Squad-Stärke und Buffs; ein deutlich schwächerer Counter verliert trotzdem.','Zerlege dein stärkstes ausgebautes Team nicht blind. Zuerst ein vollständiges Kernteam aus fünf Helden entwickeln.'],
  ["Drone Chips & Komponenten","Drone Chips, Drone Components und Drone Parts sind verschiedene Gegenstände. Der Chip-Satz muss zum unterstützten Heldentyp passen.","Die vier UR-Slots: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Das erste UR-Set in dieser Reihenfolge herstellen. Firestorm trifft mit 2 und 5 Sternen mehr Ziele.","Baue einen vollständigen Kernsatz ausgewogen aus. Prüfe Rolle, Heldentyp, Sternvorschau und Materialnamen im Upgrade-Fenster.","Parts oder Components nicht mit Chips verwechseln und keinen Zweitsquad-Satz vor dem Kernteam hochsternen."],
  ['UR-Ausrüstung & Blueprints','Bringe zuerst die goldene Legendary-Ausrüstung der fünf Kernhelden auf Level 40. Gebündelte Upgrades sind stärker als dünne Verteilung.','Für Kimberly, DVA und Tesla zuerst Railgun/Cannon, dann Chip. Für Murphy, Williams, Lucius und Carlie zuerst Armor, dann Radar. Legendary Blueprints schalten Sterne frei; Mythic Blueprints kommen später.','Prüfe in der Vorschau die nächste Sternanforderung und kombiniere große Upgrades bei Bedarf mit einem aktiven Punkte-Event.','Blueprint-Bedarf hängt von Stern und Version ab. Keine erfundenen Fixsummen verwenden und teure Materialien nicht auf alle Squads verteilen.'],
  ['Shop-Kaufprioritäten','Jeder Shop hat eine eigene Währung. Kaufe Engpässe statt Regale leer; besonders F2P braucht Reserven.','VIP: wöchentliche Stamina, ausgewählte Speedups und UR Shards nur bei genügend Reserve. Honor: hauptsächlich für Legendary Gear Blueprints sparen. Alliance: für die RZSN-Samstagsregel immer 8h/24h Shields reservieren, danach UR Shards, Drone Parts und Speedups nach Bedarf. Campaign: Ressourcenboxen, vor allem Gold nahe HQ30, Legendary Campaign Chests, Drone Parts oder universelle EW Shards je nach Bestand.','Vor dem Kauf Währungssymbol, Bestand und Reset prüfen. Preise und Angebot unterscheiden sich nach Server und Version.','Die Shield-Reserve niemals für Komfortkäufe ausgeben. Genannte Preise wären nicht garantiert.'],
  ['Wasserfall-Truppentraining','Halte mehrere Barracks auf sinnvollen Tier-Meilensteinen, um Truppen in einem Punktefenster stufenweise zu befördern.','Meilensteine: T6 bei Barracks 17, T7 bei 20, T8 bei 24, T9 bei 27 und T10 bei 30 plus Unit X. Bei 17/20/24/27 unter der Woche T6 ausbilden und am Freitag T6 → T7 → T8 → T9 befördern, wenn die Live-Regeln Beförderungen werten.','Vorher aktuelle VS-/Eventpunkte, Queues, Zeiten und Drill-Ground-Limit prüfen. Für die ganze Kette Platz lassen.','Beförderungen geben nicht immer vierfache Punkte. Die Live-Regeln sind wichtiger als alte Rechner.'],
  ["General's Trial","Wähle beim General Trial die höchste freigeschaltete Schwierigkeit. Spätere Gegner können sehr stark sein, aber du musst sie nicht allein besiegen.","Wenn ein Gegner zu stark ist, bitte im Allianzchat um Hilfe. Stärkere RZSN-Mitglieder können eine Rally starten oder deiner Rally beitreten und den Gegner gemeinsam besiegen. Nenne Schwierigkeitsstufe und Gegner-Level.","Modus, Stamina, Versuche, Belohnungen und Reset im Eventfenster prüfen. Nicht jeder Durchlauf wird von R5 geplant; im Allianzchat abstimmen.","Nicht wegen eines zu starken Gegners auf eine niedrigere Schwierigkeit wechseln. Zuerst Rally-Hilfe organisieren und die aktuellen Eventregeln prüfen."],
  ['Zombie Siege','Zombie Siege umfasst in gängigen Varianten 20 Wellen. Ein Shield stoppt die Event-Zombies nicht; Wall Defense und Reinforcement entscheiden.','Eine passende starke Verteidigungs-Squad an der Wall stationieren. Stärkere Spieler verstärken Schwächere vor späten Wellen; R4/R5 bestimmt das Event-Level.','Ankommende Wellen, Wall-Squads, Verstärkungslimit und Ausscheidungsstatus beobachten. Nach dem Ausscheiden wird die Basis nicht weiter angegriffen.','Die Fehlerregeln widersprechen sich je nach Quelle und Version. Nicht auf die Aussage „nur ein Fehler“ verlassen.'],
  ["Marshal's Guard",'Koordiniertes 30-Minuten-Schadensevent mit fünf gepanzerten Tank-Bossen und meist dreiminütigen Rallys.','Nahe am Hive bleiben, um Marschzeit zu sparen. Stärkste passende Squad senden; ein schwächeres Mitglied kann starten, wenn dadurch die Join-Reihenfolge besser wird. Zur Drill Platform spenden und Offiziersprioritäten folgen; bis zu fünf Phasen je Zielset.','Live-Zeit und Rally-Plan prüfen. RZSN nutzt oft 20:00 CET / 16:00 ST, doch die aktuelle Ankündigung gilt.','Die übliche Uhrzeit nicht fest einplanen und Schaden nicht durch ungeplante Rallys aufteilen.'],
  ['Rally- & Kampfgrundlagen','Rallys werden nicht in jedem Modus gleich bewertet. Leader, Buffs, Counter und Ziel-Freigabe sind entscheidend.','Bei Season-PvE mit Infektion kann die Resistance des Rally Leaders schwächere Teilnehmer abdecken. Im PvP zählen echte Squad-Stärke, Typ-Counter, Helden-/Gear-Buffs und Aufstellung. Strongholds nur mit autorisiertem Leader starten.','Vor dem Marsch Ziel, Leader, Teilnehmerfolge, Counter und Buffs prüfen. Samstags vorgeschriebenes Shield halten und keine verbündeten oder ungeklärten Ziele angreifen.','Resistance ersetzt keine PvP-Stärke. Ein falscher Leader oder fallendes Shield schadet der gesamten Allianz.'],
  ['Desert Storm','Zugewiesene Gruppen, schnelle Kommunikation und dauerhafte Punkte gewinnen – keine zufälligen Solo-Teleports. Reserveplätze nach echter Verfügbarkeit vergeben.','Wenn die Karte es vorsieht, Hospitals zuerst sichern oder bestreiten. Danach stabile Punktquellen wie Refineries, Science Hub/Info Center und später Nuclear Silo halten. Gestaffelt teleportieren und dem Call folgen.','Vor Eintritt Rolle, Partnergruppe, Reservestatus und aktuelle Kartenziele prüfen; Karte und Namen können variieren.','Nicht allein in eine ungestützte Lane porten oder Kills jagen, während wertvolle Gebäude leer stehen.'],
  ['Allianz-Tech & Spendenprioritäten','Spenden für Alliance Research gehen in die Allianztechnologie, nicht in dein persönliches Tech Center. Folge der R4/R5-Markierung.','Bei aktivem 20%-Bonus die bevorzugte Forschung spenden und Contribution Points sammeln. Junge Allianzen brauchen oft Economy/Development; reifes RZSN profitiert mehr von Combat ATK, DEF und HP. Territory nur für anstehende Ziele.','Markierte Forschung, Bonusstatus, Kosten und aktuellen Offiziers-Call vor der Spende prüfen.','Goldspenden sind bei knappen Ressourcen nicht verpflichtend. Spenden nicht auf unfreigegebene Zweige verstreuen.'],
  ['Minister- & Capitol-Buffs','Titel oder Buff müssen vor dem Start aktiv sein. Bereits laufende Forschung oder Bauten werden normalerweise nicht rückwirkend verkürzt.','Secretary of Science vor langer Forschung, Co-Builder vor einem Bau anfragen. Bei zwei Tech Centers beide Queues auf das Titelfenster vorbereiten. Co-operative Research und Research Now sind Engineer Skills mit eigenen Timern.','Titel am Profil kontrollieren und erst dann starten. Skillbeschreibung und aktiven Timer vor Research Now prüfen.','Prozentwerte nicht einfach addieren und nie annehmen, dass ein später Titel rückwirkend wirkt.']
]);

add('uk',[
  ['Герої та побудова загону','Став двох героїв попереду й трьох позаду. П’ять героїв одного типу дають повний бонус Tank, Aircraft або Missile.','Tank: Murphy і Williams спереду; Kimberly, Stetmann, Marshall ззаду. Aircraft: Carlie і Lucius спереду; DVA, Morrison, Schuyler ззаду. Missile: Adam і McGregor спереду; Tesla, Fiona, Swift ззаду. Air сильніший за Tank, Tank — за Missile, Missile — за Air.','Захисники мають бути саме у видимому передньому ряду. Порівнюй фактичну силу та бонуси: значно слабший контрзагін усе одно програє.','Не руйнуй найсильніший розвинений загін заради шаблону. Спочатку збудуй одну повну основну п’ятірку.'],
  ["Drone Chips і компоненти","Drone Chips, Drone Components та Drone Parts — різні предмети. Набір чипів має відповідати типу героїв.","Чотири UR-слоти: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Перший UR-набір виготовляй у цьому порядку. Firestorm на 2 і 5 зірках вражає більше цілей.","Рівномірно розвивай один повний основний набір. У вікні покращення перевіряй роль, тип героя, зірковий ефект і назву матеріалу.","Не плутай Parts чи Components із Chips і не розвивай другий загін раніше основного набору."],
  ['UR-спорядження та Blueprints','Спочатку доведи золоте Legendary-спорядження основної п’ятірки до 40 рівня. Зосереджені вкладення кращі за розпорошення.','Kimberly, DVA і Tesla: спочатку Railgun/Cannon, потім Chip. Murphy, Williams, Lucius і Carlie: спочатку Armor, потім Radar. Legendary Blueprints відкривають зірки; Mythic Blueprints потрібні пізніше.','У попередньому перегляді перевіряй вимоги наступної зірки та за можливості поєднуй великі покращення з активним очковим івентом.','Потреба в Blueprints залежить від зірки й версії. Не вір фіксованим сумам і не роздавай дорогі матеріали всім загонам.'],
  ['Пріоритети покупок у магазинах','Кожен магазин має свою валюту. Купуй те, що прибирає вузьке місце; F2P не варто бездумно очищати полиці.','VIP: щотижнева Stamina, вибрані прискорення й UR shards лише за достатнього запасу. Honor: переважно збирай на Legendary Gear Blueprints. Alliance: завжди залишай 8h/24h shields для суботньої політики RZSN, потім UR shards, Drone Parts і прискорення. Campaign: коробки ресурсів, особливо золото біля HQ30, Legendary Campaign chests, Drone Parts або універсальні EW shards за наявністю.','Перед покупкою перевір валюту, залишок і час скидання. Ціни та асортимент залежать від сервера й версії.','Не витрачай запас shields на дрібниці. Жодна точна ціна тут не гарантується.'],
  ['Каскадне тренування військ','Тримай кілька Barracks на корисних рівнях, щоб послідовно підвищувати війська під час очкового вікна.','Рубежі: T6 на Barracks 17, T7 на 20, T8 на 24, T9 на 27, T10 на 30 плюс Unit X. За рівнів 17/20/24/27 тренуй T6 протягом тижня, а в п’ятницю підвищуй T6 → T7 → T8 → T9, якщо чинні правила дають очки.','До старту перевір поточні правила VS/івенту, черги, час і місткість Drill Ground. Залиши місце для всього ланцюга.','Підвищення не завжди дає учетверо більше очок. Орієнтуйся на живий екран події, а не старий калькулятор.'],
  ["General's Trial","Вибирай найвищу відкриту складність General's Trial. Пізніші вороги можуть бути надто сильними для одного гравця, але союз допоможе.","Якщо ворог занадто сильний, попроси допомогу в чаті альянсу. Сильні учасники RZSN можуть почати rally або приєднатися до твоєї і перемогти разом. Напиши складність і рівень ворога.","Перевір у події режим, вартість Stamina, спроби, нагороди та скидання: версії різняться. Узгоджуй у чаті, не очікуй розкладу R5 для кожного Trial.","Не знижуй складність лише через одного сильного ворога. Спочатку попроси підтримку rally та перевір правила події."],
  ['Zombie Siege','У поширених версіях Zombie Siege має 20 хвиль. Shield не зупиняє зомбі події — виживання залежить від Wall Defense та підкріплень.','Постав на стіну справді сильний оборонний загін. Сильніші гравці підсилюють слабших перед пізніми хвилями; рівень події визначають R4/R5.','Стеж за хвилями, загонами на стіні, місткістю підкріплення й вибуттям. Після вибуття база більше не отримує атак у цьому запуску.','Правила поразки відрізняються у джерелах і версіях. Не покладайся на твердження «лише одна помилка».'],
  ["Marshal's Guard",'Це скоординована 30-хвилинна подія на шкоду з п’ятьма броньованими Tank-босами та зазвичай трихвилинними rally.','Будь біля hive, щоб скоротити марш. Надсилай найсильніший доречний загін; слабший учасник може стартувати для кращого порядку входу. Донать у drill platform і виконуй пріоритети офіцерів — до п’яти фаз на набір цілей.','Перевір живий час і план rally. RZSN часто грає о 20:00 CET / 16:00 ST, але чинне оголошення важливіше.','Не вважай звичний час постійним і не розділяй шкоду самовільними rally.'],
  ['Основи rally та бою','Rally оцінюється по-різному в різних режимах. Важливі лідер, buffs, контртип і дозвіл на ціль.','У Season PvE з інфекцією resistance лідера rally може покривати слабших учасників. У PvP порівнюй реальну силу, контртип, бонуси героїв/спорядження та склад маршу. Stronghold запускає лише дозволений лідер.','Перед маршем перевір ціль, лідера, порядок учасників, цикл контртипів і активні buffs. У суботу тримай потрібний shield і не бий союзні чи недозволені цілі.','Resistance не замінює PvP-силу. Неправильний лідер або втрачений shield шкодять усьому альянсу.'],
  ['Desert Storm','Перемагають призначені групи, швидкий зв’язок і стабільні очки, а не випадкові одиночні телепорти. Резерв — за реальною доступністю.','Якщо карта це підтримує, спочатку захищай або відбивай hospitals, потім утримуй refineries, Science Hub/Info Center і Nuclear Silo після відкриття. Телепортуйтесь хвилями й рухайтесь до оголошеного фокуса.','До входу перевір роль, групу, статус резерву й поточні об’єкти карти; схема й назви можуть змінюватися.','Не телепортуйся один у непідтриману лінію й не женись за вбивствами, залишаючи важливі споруди.'],
  ['Технології альянсу та пожертви','Пожертви Alliance Research ідуть у технології альянсу, а не у твій особистий Tech Center. Донать у виділений R4/R5 напрям.','Якщо активний бонус 20%, обирай рекомендоване дослідження й отримуй contribution points. Молодим альянсам корисні Economy/Development; зрілому RZSN — Combat ATK, DEF і HP. Territory лише під близьку потребу.','Перед пожертвою перевір підсвічене дослідження, бонус, вартість і актуальну вказівку офіцерів.','Пожертви золотом не обов’язкові за браку ресурсів. Не розпорошуй внески по неузгоджених гілках.'],
  ['Міністерські та Capitol buffs','Отримай титул або buff до натискання Start. Він зазвичай не скорочує вже запущені дослідження чи будівництво.','Проси Secretary of Science перед довгим дослідженням, Co-Builder — перед будівництвом. З двома Tech Centers підготуй обидві черги до вікна титулу. Co-operative Research і Research Now — Engineer skills з окремими таймерами.','Переконайся, що титул активний у профілі, і лише тоді запускай дію. Перед Research Now перевір опис та таймер skill.','Не складай відсотки простою арифметикою й не очікуй зворотної дії пізнього титулу.']
]);

add('ja',[
  ['英雄と部隊編成','前列に2人、後列に3人を配置します。同タイプ5人でTank、Aircraft、Missileの編成ボーナスを最大化できます。','Tankは前列Murphy・Williams、後列Kimberly・Stetmann・Marshall。Aircraftは前列Carlie・Lucius、後列DVA・Morrison・Schuyler。Missileは前列Adam・McGregor、後列Tesla・Fiona・Swift。Air＞Tank＞Missile＞Airの相性です。','守備役が画面上の前列にいるか確認してください。相性だけでなく実戦力とbuffも比較し、大幅に弱い対抗部隊へ無理に替えないでください。','形だけをまねて育成済みの最強部隊を崩さず、まず主力5人を完成させます。'],
  ["Drone ChipsとComponents","Drone Chips、Drone Components、Drone Partsは別のアイテムです。支援する英雄タイプに合うチップセットを選びます。","URチップの4枠：Interference＝Memory Ultra Fission、Defense＝Gravitational Resonance Armor、Initial Move＝Absolute Quantum Field、Attack＝Lethal Firestorm。最初のURセットはこの順番で作成。Firestormは星2・5で攻撃対象が増えます。","主力用の一式を偏りなく強化し、画面で役割、英雄タイプ、星効果、素材名を確認します。","PartsやComponentsをChipsと混同せず、主力一式の完成前に第二部隊へ星素材を使わないでください。"],
  ['UR GearとBlueprints','主力5人の金色Legendary Gearを先にレベル40へ。広く薄く配るより、主力への集中投資が有効です。','Kimberly・DVA・TeslaはRailgun/Cannon、次にChip。Murphy・Williams・Lucius・CarlieはArmor、次にRadar。星上げにはLegendary Blueprints、Mythic Blueprintsは後半です。','次の星の必要素材をプレビューで確認し、大型強化は必要に応じて得点イベント中に行います。','必要Blueprint数は星とバージョンで変わります。固定数を信じたり全分隊へ高価な素材を分散したりしないでください。'],
  ['ショップ購入優先度','ショップごとに通貨が異なります。F2Pは棚を空にせず、現在の不足を解消する品を優先します。','VIPは週ごとのStamina、必要なspeedups、余裕がある時だけUR shards。Honorは主にLegendary Gear Blueprintsへ温存。AllianceはRZSN土曜方針用の8h/24h shieldsを必ず確保し、次にUR shards、Drone Parts、speedups。Campaignは資源箱（HQ30付近は特にgold）、Legendary Campaign chests、Drone Parts、在庫に応じて万能EW shards。','購入前に通貨アイコン、在庫、更新時間を確認します。価格と品揃えはサーバーや版で異なります。','shield用の蓄えを便利品に使わないでください。ここでは固定価格を保証しません。'],
  ['滝式兵士訓練','複数のBarracksを節目レベルに保ち、得点期間に兵士を段階的に昇級させます。','節目はBarracks 17でT6、20でT7、24でT8、27でT9、30＋Unit XでT10。17/20/24/27なら週中にT6を訓練し、金曜の現行ルールが昇級を採点する時にT6→T7→T8→T9へ進めます。','開始前にVS/イベントの得点、キュー、所要時間、Drill Ground上限を確認し、全工程分の空きを確保します。','昇級が常に4倍得点とは限りません。古い計算表より開催中イベント画面を優先してください。'],
  ["General's Trial","General's Trialでは解放済みの最高難易度を選びます。後半の敵は一人では強すぎる場合がありますが、同盟の助けを借りられます。","敵が強すぎる場合は同盟チャットで助けを求めましょう。強いRZSNメンバーがRallyを開始するか、あなたのRallyに参加して一緒に倒せます。難易度と敵レベルも伝えましょう。","モード、Stamina消費、回数、報酬、リセットをイベント画面で確認してください。版による差があり、毎回R5主催とは限らないためチャットで調整します。","一人で倒せない敵がいるだけで難易度を下げないでください。先にRally支援を依頼し、現行のイベントルールを確認しましょう。"],
  ['Zombie Siege','一般的な仕様は20waveです。shieldではイベントゾンビを止められず、Wall Defenseとreinforcementが生存を左右します。','壁に適切な強い防衛部隊を配置します。後半wave前に強い人が弱い基地を増援し、開始レベルはR4/R5に確認します。','襲来wave、壁部隊、増援枠、脱落状態を監視します。脱落後はその回で基地への追加攻撃はありません。','失敗条件は情報源や版で異なります。「失敗は1回だけ」と決めつけず現行ルールを読んでください。'],
  ["Marshal's Guard",'一般的には30分間、装甲Tank bossが5体、rallyは3分の協力ダメージイベントです。','行軍時間を減らすためhive近くにいます。適切な最強部隊を参加させ、参加順が良くなるなら弱い人が開始しても構いません。drill platformへ寄付し、目標セットごと最大5段階まで役員指示に従います。','開催時刻とrally計画を確認します。RZSNは通常20:00 CET / 16:00 STですが、当日の告知が最優先です。','通常時刻を固定予定とみなさず、無計画なrallyで火力を分散しないでください。'],
  ['Rallyと戦闘の基本','モードごとにrallyの評価方法は異なります。リーダー、buff、相性、攻撃許可をすべて確認します。','Season PvEのinfection戦ではrally leaderのresistanceが低い参加者を補えます。PvPでは実戦力、タイプ相性、英雄・Gear buff、行軍構成を比較します。strongholdは許可されたリーダーだけが開始します。','出撃前に対象、リーダー、参加順、相性循環、buffを確認します。土曜は指定shieldを維持し、同盟先や無許可目標を攻撃しません。','resistanceはPvP戦力の代わりではありません。誤ったリーダーやshield切れは同盟全体に損害を与えます。'],
  ['Desert Storm','担当グループ、素早い連絡、継続得点で勝ちます。単独の無計画teleportは避け、reserveは実際の参加可否で決めます。','対応マップではhospitalを優先して守る・奪う。その後refineries、Science Hub/Info Center、解放後のNuclear Siloなど継続得点施設を保持します。グループごとに時間差でteleportし、指示された地点へ動きます。','入場前に役割、相方グループ、reserve状態、現行マップ目標を確認します。配置や名称は変わることがあります。','支援のないlaneへ一人で飛んだり、重要施設を空けて撃破数だけ追ったりしないでください。'],
  ['Alliance Techと寄付優先度','Alliance Researchへの寄付は個人のTech Centerではなく同盟技術に入ります。R4/R5が強調した項目へ寄付します。','推奨研究の20% bonusが有効なら利用し、contribution pointsを獲得します。初期同盟はEconomy/Development、成熟したRZSNはCombatのATK・DEF・HPが有効。Territoryは直近の必要時だけです。','寄付前に強調項目、bonus状態、残り費用、最新の役員指示を確認します。','資源が苦しい時のgold寄付は強制ではありません。未承認の枝へ分散しないでください。'],
  ['Minister / Capitol Buff','Startを押す前にtitleやbuffを受けます。開始済みの研究・建設は通常あとから短縮されません。','長期研究前にSecretary of Science、建設前にCo-Builderを依頼します。Tech Centerが2つなら両キューをtitle時間に合わせて準備。Co-operative ResearchとResearch NowはEngineer skillなので有効時間を見て使います。','プロフィールでtitle有効を確認してから開始します。Research Now前にskill説明とタイマーを確認してください。','割合を単純加算せず、あとからのtitleが遡って効くと思わないでください。']
]);

add('fr',[
  ['Héros et formations d’escouade','Place deux héros devant et trois derrière. Cinq héros du même type donnent le bonus complet Tank, Aircraft ou Missile.','Tank : Murphy et Williams devant ; Kimberly, Stetmann, Marshall derrière. Aircraft : Carlie et Lucius devant ; DVA, Morrison, Schuyler derrière. Missile : Adam et McGregor devant ; Tesla, Fiona, Swift derrière. Air bat Tank, Tank bat Missile, Missile bat Air.','Les défenseurs doivent être visibles au premier rang. Compare la puissance réelle et les buffs : une équipe de contre beaucoup plus faible peut perdre.','Ne démantèle pas ton équipe la mieux développée pour copier un modèle. Termine d’abord un noyau de cinq héros.'],
  ["Drone Chips et composants","Drone Chips, Drone Components et Drone Parts sont trois objets différents. Choisis un jeu de chips adapté au type de héros.","Quatre slots UR : Interference = Memory Ultra Fission ; Defense = Gravitational Resonance Armor ; Initial Move = Absolute Quantum Field ; Attack = Lethal Firestorm. Fabrique le premier set UR dans cet ordre. Firestorm frappe davantage de cibles à 2 et 5 étoiles.","Monte un jeu principal complet de façon équilibrée. Vérifie rôle, type de héros, aperçu d’étoile et nom du matériau dans l’écran d’amélioration.","Ne confonds pas Parts, Components et Chips, et n’investis pas dans la deuxième escouade avant le jeu principal."],
  ['Équipement UR et Blueprints','Monte d’abord l’équipement Legendary doré niveau 40 des cinq héros principaux. Concentrer les ressources vaut mieux que les disperser.','Pour Kimberly, DVA et Tesla : Railgun/Cannon puis Chip. Pour Murphy, Williams, Lucius et Carlie : Armor puis Radar. Les Legendary Blueprints ouvrent les étoiles ; les Mythic Blueprints viennent plus tard.','Consulte l’aperçu de la prochaine étoile et synchronise les grosses améliorations avec un événement de points si utile.','Les besoins en Blueprints varient selon l’étoile et la version. Évite les totaux fixes inventés et la dispersion sur toutes les équipes.'],
  ['Priorités d’achat des boutiques','Chaque boutique a sa monnaie. Achète pour lever un blocage ; un joueur F2P ne doit pas vider les rayons sans plan.','VIP : Stamina hebdomadaire, certains speedups et UR shards seulement avec une bonne réserve. Honor : économise surtout pour les Legendary Gear Blueprints. Alliance : garde toujours des shields 8h/24h pour la règle RZSN du samedi, puis UR shards, Drone Parts et speedups. Campaign : boîtes de ressources, surtout gold vers HQ30, Legendary Campaign chests, Drone Parts ou universal EW shards selon le stock.','Vérifie l’icône de monnaie, le stock et le reset. Prix et choix peuvent varier selon le serveur et la version.','Ne dépense jamais la réserve de shields pour du confort. Aucun prix exact n’est garanti ici.'],
  ['Entraînement de troupes en cascade','Garde plusieurs Barracks aux niveaux clés afin de promouvoir les troupes en chaîne pendant une fenêtre de points.','Paliers : T6 au Barracks 17, T7 au 20, T8 au 24, T9 au 27, T10 au 30 plus Unit X. Avec 17/20/24/27, entraîne des T6 la semaine puis promeus T6 → T7 → T8 → T9 le vendredi si les règles actives récompensent les promotions.','Avant de commencer, vérifie score VS/événement, files, durée et capacité du Drill Ground. Garde assez de place pour toute la chaîne.','Une promotion ne vaut pas toujours quatre fois plus. Fie-toi à l’écran actif, pas à un ancien calculateur.'],
  ["General's Trial","Choisis la difficulté la plus élevée déjà débloquée dans General's Trial. Certains ennemis seront trop puissants en solo, mais l’alliance peut aider.","Si un ennemi est trop fort, demande de l’aide dans le chat de l’alliance. Les membres RZSN plus puissants peuvent lancer une rally ou rejoindre la tienne pour le vaincre ensemble. Indique la difficulté et le niveau de l’ennemi.","Vérifie mode, coût, essais, récompenses et reset dans l’interface, car des variantes existent. Coordonne-toi dans le chat sans supposer un horaire R5 à chaque Trial.","Ne choisis pas une difficulté inférieure à cause d’un seul ennemi trop puissant. Demande d’abord une rally et vérifie les règles actuelles."],
  ['Zombie Siege','Zombie Siege comporte généralement 20 vagues. Un shield n’arrête pas les zombies de l’événement : Wall Defense et renforts décident.','Place une vraie escouade défensive forte sur le mur. Les joueurs forts renforcent les bases faibles avant les dernières vagues ; demande à R4/R5 le niveau choisi.','Surveille les vagues, les escouades du mur, la capacité de renfort et l’élimination. Une base éliminée ne subit plus d’attaque pendant cette manche.','Les règles d’échec diffèrent selon les sources et versions. Ne te fie pas à « une seule défaite » ; lis les règles actives.'],
  ["Marshal's Guard",'Événement coordonné de 30 minutes avec cinq boss Tank blindés et des rallys de trois minutes dans les versions courantes.','Reste près du hive pour raccourcir la marche. Envoie ta meilleure escouade adaptée ; un membre plus faible peut lancer pour optimiser l’ordre d’entrée. Donne à la drill platform et suis les priorités des officiers, jusqu’à cinq phases par série.','Vérifie l’heure et le plan du jour. RZSN joue souvent à 20:00 CET / 16:00 ST, mais l’annonce actuelle fait foi.','Ne considère pas l’horaire habituel comme permanent et ne disperse pas les dégâts avec des rallys non prévus.'],
  ['Bases des rallys et du combat','Une rally ne se calcule pas pareil dans tous les modes. Chef, buffs, contres et autorisation de cible comptent.','En PvE Season avec infection, la resistance du rally leader peut couvrir des participants plus faibles. En PvP, compare puissance réelle, contre de type, buffs héros/équipement et composition. Seul un chef autorisé lance sur un stronghold.','Avant de marcher, contrôle cible, chef, ordre d’entrée, cycle des contres et buffs actifs. Le samedi, garde le shield requis et n’attaque aucune cible alliée ou non autorisée.','La resistance ne remplace pas la puissance PvP. Un mauvais chef ou un shield perdu pénalise toute l’alliance.'],
  ['Desert Storm','Gagne avec des rôles assignés, une communication rapide et des points continus, pas avec des téléportations solo. La réserve dépend de la disponibilité réelle.','Quand la carte le permet, sécurise d’abord les hospitals, puis tiens les sources régulières : refineries, Science Hub/Info Center et Nuclear Silo à son ouverture. Téléportez-vous par groupes décalés vers la cible annoncée.','Avant l’entrée, confirme rôle, groupe, réserve et objectifs actuels ; carte et noms peuvent changer.','Ne te téléporte pas seul sur une voie sans soutien et ne chasse pas les kills en abandonnant les structures.'],
  ['Tech d’alliance et priorités de dons','Les dons Alliance Research alimentent la technologie d’alliance, pas ton Tech Center personnel. Donne sur la recommandation R4/R5 surlignée.','Profite du bonus de 20 % s’il est actif et collecte les contribution points. Une jeune alliance privilégie souvent Economy/Development ; un RZSN mûr gagne davantage avec Combat ATK, DEF et HP. Territory seulement pour un besoin proche.','Avant le don, contrôle la recherche surlignée, le bonus, le coût et la consigne actuelle des officiers.','Les dons en gold ne sont pas obligatoires si tes ressources sont tendues. Ne disperse pas les dons.'],
  ['Buffs de ministre et du Capitol','Obtiens le titre ou buff avant d’appuyer sur Start. Il ne raccourcit normalement pas une recherche ou construction déjà lancée.','Demande Secretary of Science avant une longue recherche et Co-Builder avant une construction. Avec deux Tech Centers, prépare les deux files pour la fenêtre du titre. Co-operative Research et Research Now sont des skills Engineer à minuter.','Vérifie le titre actif sur ton profil, puis lance l’action. Relis la description et le timer avant Research Now.','N’additionne pas simplement les pourcentages et ne suppose pas qu’un titre tardif agit rétroactivement.']
]);

add('it',[
  ['Eroi e formazioni squadra','Metti due eroi davanti e tre dietro. Cinque eroi dello stesso tipo attivano il bonus completo Tank, Aircraft o Missile.','Tank: Murphy e Williams davanti; Kimberly, Stetmann, Marshall dietro. Aircraft: Carlie e Lucius davanti; DVA, Morrison, Schuyler dietro. Missile: Adam e McGregor davanti; Tesla, Fiona, Swift dietro. Air batte Tank, Tank batte Missile, Missile batte Air.','I difensori devono essere visibili in prima fila. Confronta potenza reale e buff: una squadra counter molto più debole può comunque perdere.','Non smontare la squadra più sviluppata solo per copiare una formazione. Completa prima un nucleo di cinque.'],
  ["Drone Chips e componenti","Drone Chips, Drone Components e Drone Parts sono oggetti diversi. Abbina il set di chip al tipo di eroe supportato.","Quattro slot UR: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Crea il primo set UR in quest'ordine. Firestorm a 2 e 5 stelle colpisce più bersagli.","Potenzia in modo equilibrato un set principale completo. Controlla ruolo, tipo eroe, anteprima stelle e nome del materiale.","Non confondere Parts o Components con Chips e non investire nel secondo set prima del principale."],
  ['Equipaggiamento UR e Blueprints','Porta prima al livello 40 l’equipaggiamento Legendary dorato dei cinque eroi principali. Concentrare rende più che distribuire.','Kimberly, DVA e Tesla: prima Railgun/Cannon, poi Chip. Murphy, Williams, Lucius e Carlie: prima Armor, poi Radar. I Legendary Blueprints sbloccano le stelle; i Mythic Blueprints servono più avanti.','Controlla nell’anteprima il requisito della prossima stella e abbina gli upgrade importanti a un evento punti attivo quando conviene.','I Blueprints richiesti cambiano per stella e versione. Evita totali fissi inventati e dispersione su tutte le squadre.'],
  ['Priorità acquisti nei negozi','Ogni negozio usa una valuta diversa. Compra ciò che rimuove un blocco; chi è F2P non deve svuotare gli scaffali.','VIP: Stamina settimanale, speedups selezionati e UR shards solo con riserve. Honor: conserva soprattutto per Legendary Gear Blueprints. Alliance: tieni sempre shields 8h/24h per la regola RZSN del sabato, poi UR shards, Drone Parts e speedups. Campaign: casse risorse, soprattutto gold vicino a HQ30, Legendary Campaign chests, Drone Parts o universal EW shards secondo lo stock.','Prima di comprare controlla valuta, scorte e reset. Prezzi e assortimento cambiano tra server e versioni.','Non spendere la riserva shields per comodità. Nessun prezzo esatto è garantito.'],
  ['Addestramento truppe a cascata','Mantieni più Barracks ai livelli chiave per promuovere le truppe in sequenza durante una finestra punti.','Soglie: T6 a Barracks 17, T7 a 20, T8 a 24, T9 a 27, T10 a 30 più Unit X. Con 17/20/24/27 addestra T6 in settimana, poi promuovi T6 → T7 → T8 → T9 venerdì se le regole attive assegnano punti.','Controlla punteggio VS/evento, code, tempi e capacità Drill Ground. Lascia spazio per l’intera catena.','Le promozioni non valgono sempre quattro volte. Segui la schermata evento attiva, non un vecchio calcolatore.'],
  ["General's Trial","Scegli la difficoltà più alta già sbloccata in General's Trial. Gli ultimi nemici possono essere troppo forti da soli, ma l’alleanza può aiutarti.","Se un nemico è troppo forte, chiedi aiuto nella chat dell’alleanza. I membri RZSN più forti possono avviare una rally o entrare nella tua per sconfiggerlo insieme. Indica difficoltà e livello del nemico.","Controlla modalità, costo, tentativi, ricompense e reset nell’evento perché esistono varianti. Coordinati in chat senza aspettarti sempre un programma R5.","Non abbassare la difficoltà solo perché un nemico è troppo forte in solo. Prima chiedi supporto rally e controlla le regole dell’evento."],
  ['Zombie Siege','Zombie Siege ha comunemente 20 ondate. Uno shield non ferma gli zombie dell’evento: servono Wall Defense e rinforzi.','Metti una vera squadra difensiva forte sul muro. I giocatori forti rinforzano le basi deboli prima delle ondate finali; R4/R5 indica il livello evento.','Sorveglia ondate, squadre sul muro, capacità rinforzi ed eliminazione. Una base eliminata non riceve altri attacchi nella sessione.','Le regole di fallimento variano tra fonti e versioni. Non fidarti di “un solo errore”; leggi le regole attive.'],
  ["Marshal's Guard",'Evento coordinato di 30 minuti con cinque boss Tank corazzati e rally da tre minuti nelle versioni comuni.','Resta vicino all’hive per ridurre la marcia. Invia la squadra adatta più forte; un membro debole può avviare se migliora l’ordine d’ingresso. Dona alla drill platform e segui gli ufficiali, fino a cinque fasi per serie.','Controlla orario e piano live. RZSN usa spesso 20:00 CET / 16:00 ST, ma vale l’annuncio corrente.','Non rendere fisso l’orario abituale e non dividere il danno con rally fuori piano.'],
  ['Fondamenti di rally e combattimento','Una rally non funziona allo stesso modo in ogni modalità. Contano leader, buff, counter e autorizzazione del bersaglio.','Nel PvE Season con infection, la resistance del rally leader può coprire partecipanti più bassi. In PvP confronta potenza reale, tipo counter, buff eroi/equipaggiamento e composizione. Solo un leader autorizzato avvia stronghold.','Prima di marciare controlla bersaglio, leader, ordine, ciclo counter e buff. Sabato mantieni lo shield richiesto e non colpire alleati o bersagli non autorizzati.','La resistance non sostituisce la forza PvP. Leader sbagliato o shield scaduto danneggiano tutta l’alleanza.'],
  ['Desert Storm','Vincono ruoli assegnati, comunicazione rapida e punti costanti, non teleport casuali in solitaria. Le riserve seguono la disponibilità reale.','Se la mappa lo prevede, proteggi o contesta prima gli hospitals; poi mantieni refineries, Science Hub/Info Center e Nuclear Silo quando apre. Teleport scaglionati a gruppi verso il focus chiamato.','Prima di entrare conferma ruolo, gruppo, riserva e obiettivi correnti; mappa e nomi possono variare.','Non teleportarti solo in una corsia senza supporto e non inseguire kill lasciando vuote le strutture.'],
  ['Tech alleanza e priorità donazioni','Le donazioni Alliance Research vanno alla tecnologia dell’alleanza, non al Tech Center personale. Segui la raccomandazione evidenziata da R4/R5.','Usa il bonus preferito del 20% quando attivo e raccogli contribution points. All’inizio convengono Economy/Development; per un RZSN maturo Combat ATK, DEF e HP. Territory solo per necessità vicine.','Controlla ricerca evidenziata, bonus, costo e chiamata ufficiali prima di donare.','Le donazioni gold non sono obbligatorie se le risorse scarseggiano. Non disperdere contributi.'],
  ['Buff Minister e Capitol','Ottieni titolo o buff prima di premere Start. Di norma non accorcia ricerca o costruzione già iniziata.','Chiedi Secretary of Science prima di una ricerca lunga e Co-Builder prima di costruire. Con due Tech Centers prepara entrambe le code. Co-operative Research e Research Now sono skill Engineer con timer propri.','Verifica il titolo attivo nel profilo, poi avvia. Controlla descrizione e timer prima di Research Now.','Non sommare le percentuali in modo semplice e non presumere un effetto retroattivo.']
]);

add('id',[
  ['Hero & formasi skuad','Tempatkan dua hero di depan dan tiga di belakang. Lima hero satu tipe memberi bonus penuh Tank, Aircraft, atau Missile.','Tank: Murphy dan Williams depan; Kimberly, Stetmann, Marshall belakang. Aircraft: Carlie dan Lucius depan; DVA, Morrison, Schuyler belakang. Missile: Adam dan McGregor depan; Tesla, Fiona, Swift belakang. Air mengalahkan Tank, Tank mengalahkan Missile, Missile mengalahkan Air.','Pastikan defender terlihat di baris depan. Bandingkan kekuatan nyata dan buff; skuad counter yang jauh lebih lemah tetap bisa kalah.','Jangan bongkar skuad terkuat hanya untuk meniru formasi. Selesaikan lima hero inti dahulu.'],
  ["Drone Chips & komponen","Drone Chips, Drone Components, dan Drone Parts adalah item berbeda. Cocokkan set chip dengan tipe hero yang didukung.","Empat slot UR: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Buat set UR pertama dengan urutan ini. Firestorm bintang 2 dan 5 mengenai lebih banyak target.","Naikkan satu set inti lengkap secara seimbang. Periksa peran, tipe hero, pratinjau bintang, dan nama bahan di layar upgrade.","Jangan samakan Parts atau Components dengan Chips dan jangan dahulukan set skuad kedua."],
  ['UR Gear & Blueprints','Naikkan dahulu gear Legendary emas level 40 untuk lima hero inti. Investasi terpusat lebih baik daripada tersebar tipis.','Kimberly, DVA, Tesla: Railgun/Cannon lalu Chip. Murphy, Williams, Lucius, Carlie: Armor lalu Radar. Legendary Blueprints membuka bintang; Mythic Blueprints diperlukan nanti.','Periksa kebutuhan bintang berikutnya dan, bila berguna, lakukan upgrade besar saat event skor aktif.','Jumlah Blueprint berubah menurut bintang dan versi. Jangan percaya total tetap atau menyebar bahan mahal ke semua skuad.'],
  ['Prioritas belanja toko','Setiap toko memakai mata uang sendiri. Beli untuk mengatasi hambatan; pemain F2P jangan menghabiskan semua stok tanpa rencana.','VIP: Stamina mingguan, speedups pilihan, dan UR shards hanya saat mampu. Honor: utamakan simpan untuk Legendary Gear Blueprints. Alliance: selalu cadangkan shields 8h/24h untuk aturan Sabtu RZSN, lalu UR shards, Drone Parts, dan speedups. Campaign: kotak sumber daya, terutama gold mendekati HQ30, Legendary Campaign chests, Drone Parts, atau universal EW shards sesuai stok.','Periksa ikon mata uang, stok, dan reset. Harga serta isi toko dapat berbeda per server dan versi.','Jangan gunakan cadangan shields untuk barang praktis. Tidak ada harga pasti yang dijamin.'],
  ['Latihan pasukan waterfall','Pertahankan beberapa Barracks di level penting agar pasukan bisa dipromosikan berantai saat jendela skor.','Tahap: T6 di Barracks 17, T7 di 20, T8 di 24, T9 di 27, T10 di 30 plus Unit X. Dengan 17/20/24/27, latih T6 sepanjang minggu lalu promosikan T6 → T7 → T8 → T9 pada Jumat bila aturan aktif memberi skor.','Periksa skor VS/event, antrean, waktu, dan kapasitas Drill Ground. Sisakan ruang untuk seluruh rantai.','Promosi tidak selalu memberi skor empat kali. Ikuti layar event aktif, bukan kalkulator lama.'],
  ["General's Trial","Pilih tingkat kesulitan tertinggi yang sudah terbuka di General's Trial. Musuh berikutnya mungkin terlalu kuat untuk dilawan sendiri, tetapi aliansi bisa membantu.","Jika musuh terlalu kuat, minta bantuan di chat aliansi. Anggota RZSN yang lebih kuat dapat memulai rally atau bergabung dengan rally milikmu untuk mengalahkannya bersama. Sebutkan kesulitan dan level musuh.","Periksa mode, biaya, percobaan, hadiah, dan reset karena versi bisa berbeda. Koordinasi di chat; tidak semua Trial dijadwalkan R5.","Jangan turunkan tingkat kesulitan hanya karena satu musuh terlalu kuat saat solo. Minta bantuan rally dahulu dan periksa aturan event aktif."],
  ['Zombie Siege','Zombie Siege biasanya memiliki 20 wave. Shield tidak menghentikan zombie event; Wall Defense dan reinforcement menentukan ketahanan.','Pasang skuad defense kuat yang tepat di wall. Pemain kuat memperkuat base lemah sebelum wave akhir; tanyakan level event kepada R4/R5.','Pantau wave, skuad wall, kapasitas reinforcement, dan status eliminasi. Setelah tereliminasi, base tidak diserang lagi dalam putaran itu.','Aturan gagal berbeda antar sumber dan versi. Jangan percaya klaim “hanya satu kegagalan”; baca aturan aktif.'],
  ["Marshal's Guard",'Event damage terkoordinasi 30 menit dengan lima boss Tank berlapis baja dan rally tiga menit pada versi umum.','Tetap dekat hive untuk mengurangi waktu march. Kirim skuad terkuat yang sesuai; anggota lebih lemah boleh memulai jika urutan join lebih baik. Donasi ke drill platform dan ikuti prioritas officer, maksimal lima fase per set target.','Periksa waktu dan rencana live. RZSN sering memakai 20:00 CET / 16:00 ST, tetapi pengumuman terbaru berlaku.','Jangan menganggap jam biasa selalu tetap atau membagi damage dengan rally tanpa izin.'],
  ['Dasar rally & pertempuran','Perhitungan rally berbeda antar mode. Leader, buff, counter, dan izin target semuanya penting.','Dalam PvE Season dengan infection, resistance rally leader dapat melindungi peserta yang lebih rendah. Dalam PvP bandingkan kekuatan nyata, tipe counter, buff hero/gear, dan komposisi. Stronghold hanya dimulai leader resmi.','Sebelum march, cek target, leader, urutan peserta, siklus counter, dan buff. Pada Sabtu pertahankan shield wajib dan jangan serang sekutu atau target tanpa izin.','Resistance bukan pengganti kekuatan PvP. Leader salah atau shield jatuh merugikan seluruh aliansi.'],
  ['Desert Storm','Menang lewat pembagian peran, komunikasi cepat, dan skor berkelanjutan—bukan teleport solo acak. Reserve mengikuti ketersediaan nyata.','Jika ada di map, lindungi atau rebut hospitals dahulu, lalu tahan refineries, Science Hub/Info Center, dan Nuclear Silo saat terbuka. Teleport per kelompok secara bergiliran menuju fokus panggilan.','Konfirmasi peran, kelompok, status reserve, dan objektif map sebelum masuk; layout dan nama bisa berubah.','Jangan teleport sendirian ke jalur tanpa dukungan atau mengejar kill sambil meninggalkan bangunan penting.'],
  ['Alliance Tech & prioritas donasi','Donasi Alliance Research masuk ke teknologi aliansi, bukan Tech Center pribadi. Donasi ke rekomendasi yang ditandai R4/R5.','Pakai bonus preferred tech 20% saat aktif dan kumpulkan contribution points. Aliansi awal biasanya butuh Economy/Development; RZSN matang lebih diuntungkan Combat ATK, DEF, HP. Territory hanya untuk kebutuhan dekat.','Periksa riset yang ditandai, status bonus, biaya, dan arahan officer sebelum donasi.','Donasi gold tidak wajib saat sumber daya terbatas. Jangan menyebar donasi ke cabang tanpa persetujuan.'],
  ['Buff Minister / Capitol','Dapatkan title atau buff sebelum menekan Start. Biasanya buff tidak mempersingkat riset atau konstruksi yang sudah berjalan.','Minta Secretary of Science sebelum riset panjang dan Co-Builder sebelum membangun. Dengan dua Tech Centers, siapkan kedua antrean. Co-operative Research dan Research Now adalah skill Engineer dengan timer aktif.','Pastikan title aktif di profil, baru mulai. Periksa deskripsi dan timer sebelum Research Now.','Jangan menjumlahkan persentase secara sederhana atau menganggap title terlambat berlaku surut.']
]);

add('ar',[
  ['الأبطال وتشكيلات الفرق','ضع بطلين في الصف الأمامي وثلاثة في الخلف. يمنح خمسة أبطال من النوع نفسه مكافأة Tank أو Aircraft أو Missile الكاملة.','Tank: ‏Murphy وWilliams في الأمام؛ Kimberly وStetmann وMarshall في الخلف. Aircraft: ‏Carlie وLucius أمامًا؛ DVA وMorrison وSchuyler خلفًا. Missile: ‏Adam وMcGregor أمامًا؛ Tesla وFiona وSwift خلفًا. Air يتفوق على Tank، وTank على Missile، وMissile على Air.','تأكد أن المدافعين ظاهرون في الصف الأمامي. قارن القوة الفعلية والـbuffs؛ قد يخسر فريق counter أضعف بكثير.','لا تفكك أقوى فريق مطوّر لمجرد نسخ تشكيل. أكمل أولًا خمسة أبطال أساسيين.'],
  ["Drone Chips والمكوّنات","إن Drone Chips وDrone Components وDrone Parts عناصر مختلفة. طابق مجموعة الشرائح مع نوع الأبطال الذي تدعمه.","خانات UR الأربع: Interference = Memory Ultra Fission؛ Defense = Gravitational Resonance Armor؛ Initial Move = Absolute Quantum Field؛ Attack = Lethal Firestorm. اصنع أول مجموعة UR بهذا الترتيب. Firestorm عند النجمتين 2 و5 يصيب أهدافاً إضافية.","طوّر مجموعة أساسية كاملة بتوازن، وتحقق من الدور ونوع البطل ومعاينة النجوم واسم المادة في شاشة الترقية.","لا تخلط Parts أو Components مع Chips، ولا تسبق الفريق الأساسي بمجموعة الفريق الثاني."],
  ['عتاد UR وBlueprints','ارفع العتاد Legendary الذهبي للأبطال الخمسة الأساسيين إلى المستوى 40 أولًا. التركيز أفضل من تشتيت الموارد.','لـKimberly وDVA وTesla: ‏Railgun/Cannon ثم Chip. ولـMurphy وWilliams وLucius وCarlie: ‏Armor ثم Radar. تفتح Legendary Blueprints النجوم، أما Mythic Blueprints فتأتي لاحقًا.','تحقق من متطلبات النجمة التالية، ونفّذ الترقيات الكبيرة أثناء فعالية نقاط نشطة عندما يفيد ذلك.','تختلف متطلبات Blueprints حسب النجمة والإصدار. لا تعتمد أرقامًا ثابتة ولا توزع المواد الغالية على كل الفرق.'],
  ['أولويات الشراء من المتاجر','لكل متجر عملته الخاصة. اشترِ ما يحل عنق الزجاجة؛ وعلى لاعب F2P ألا يفرغ الرفوف بلا خطة.','VIP: ‏Stamina الأسبوعية وspeedups مختارة وUR shards عند توفر الفائض. Honor: ادخر أساسًا لـLegendary Gear Blueprints. Alliance: احتفظ دائمًا بـshields لمدة 8h/24h لسياسة RZSN يوم السبت، ثم UR shards وDrone Parts وspeedups. Campaign: صناديق الموارد، وخاصة gold قرب HQ30، وLegendary Campaign chests وDrone Parts أو universal EW shards حسب المخزون.','افحص رمز العملة والمخزون ووقت reset. تختلف الأسعار والبضائع حسب الخادم والإصدار.','لا تنفق مخزون shields على مشتريات ثانوية. لا نضمن هنا أي سعر ثابت.'],
  ['تدريب القوات المتسلسل','احتفظ بعدة Barracks عند مستويات مهمة لترقية القوات كسلسلة خلال نافذة النقاط.','المراحل: T6 عند Barracks 17، وT7 عند 20، وT8 عند 24، وT9 عند 27، وT10 عند 30 مع Unit X. مع 17/20/24/27 درّب T6 خلال الأسبوع ثم رقِّ T6 → T7 → T8 → T9 يوم الجمعة إذا احتسبتها القواعد الحالية.','تحقق من نقاط VS/الفعالية والطوابير والوقت وسعة Drill Ground، واترك مساحة للسلسلة كاملة.','الترقية لا تمنح دائمًا أربعة أضعاف النقاط. اتبع شاشة الفعالية الحالية لا حاسبة قديمة.'],
  ["General's Trial","اختر أعلى مستوى صعوبة مفتوح في General's Trial. قد يكون بعض الأعداء أقوى من أن تهزمهم وحدك، لكن التحالف يستطيع المساعدة.","إذا كان العدو قوياً جداً، اطلب المساعدة في دردشة التحالف. يمكن لأعضاء RZSN الأقوى بدء Rally أو الانضمام إلى Rally الخاصة بك لهزيمته معاً. اذكر الصعوبة ومستوى العدو.","تحقق من النمط والكلفة والمحاولات والمكافآت وreset داخل الفعالية لأن النسخ تختلف. نسّق في الدردشة ولا تفترض جدول R5 لكل Trial.","لا تخفض الصعوبة بسبب عدو واحد لا تستطيع هزيمته منفرداً. اطلب دعم Rally أولاً وتحقق من قواعد الحدث الحالية."],
  ['Zombie Siege','تضم Zombie Siege عادة 20 موجة. لا يوقف shield زومبي الفعالية؛ الحسم في Wall Defense والتعزيز.','ضع فريق دفاع قويًا مناسبًا على الجدار. يعزز الأقوى قواعد الأضعف قبل الموجات المتأخرة، ويحدد R4/R5 مستوى الفعالية.','راقب الموجات وفرق الجدار وسعة التعزيز وحالة الإقصاء. بعد الإقصاء لا تتعرض القاعدة لمزيد من الهجمات في الجولة.','تختلف قواعد الفشل بين المصادر والإصدارات. لا تعتمد عبارة «فشل واحد فقط» واقرأ القواعد الحالية.'],
  ["Marshal's Guard",'فعالية ضرر منسقة لمدة 30 دقيقة تضم خمسة زعماء Tank مدرعين وrallies مدتها ثلاث دقائق غالبًا.','ابق قرب hive لتقليل زمن المسير. أرسل أقوى فريق مناسب؛ قد يبدأ عضو أضعف لتحسين ترتيب الانضمام. تبرع إلى drill platform واتبع أولويات الضباط، حتى خمس مراحل لكل مجموعة أهداف.','تحقق من وقت وخطة اليوم. تستخدم RZSN غالبًا 20:00 CET / 16:00 ST، لكن الإعلان الحالي هو المرجع.','لا تثبت الموعد المعتاد ولا تشتت الضرر بـrallies غير مخططة.'],
  ['أساسيات الـRally والقتال','لا تُحسب rally بالطريقة نفسها في كل نمط. القائد والـbuffs والـcounter وتصريح الهدف كلها مهمة.','في Season PvE مع infection قد تغطي resistance الخاصة بـrally leader المشاركين الأقل. في PvP قارن القوة الفعلية ونوع counter وbuffs الأبطال/العتاد والتشكيل. يبدأ stronghold قائد مصرح فقط.','قبل المسير افحص الهدف والقائد وترتيب المشاركين ودورة counter والـbuffs. يوم السبت حافظ على shield المطلوب ولا تضرب حليفًا أو هدفًا غير مصرح.','لا تعوض resistance قوة PvP. قائد خاطئ أو سقوط shield يضر التحالف كله.'],
  ['Desert Storm','الفوز بتوزيع الأدوار والتواصل السريع والنقاط المستمرة، لا بالـteleport الفردي العشوائي. الاحتياط حسب التوفر الحقيقي.','إذا دعمت الخريطة ذلك، احمِ أو نافس على hospitals أولًا، ثم أمسك refineries وScience Hub/Info Center وNuclear Silo عند فتحه. نفذوا teleport على دفعات إلى الهدف المنادى.','أكد دورك ومجموعتك وحالة الاحتياط وأهداف الخريطة قبل الدخول؛ قد تختلف الخريطة والأسماء.','لا تنتقل وحدك إلى مسار بلا دعم ولا تطارد القتلات وتترك المنشآت المهمة.'],
  ['تقنيات التحالف وأولوية التبرع','تذهب تبرعات Alliance Research إلى تقنية التحالف، لا إلى Tech Center الشخصي. تبرع لما يحدده R4/R5.','استخدم مكافأة التقنية المفضلة 20% عند نشاطها واجمع contribution points. يناسب التحالف الناشئ Economy/Development غالبًا؛ ويناسب RZSN الناضج Combat ATK وDEF وHP. ‏Territory لحاجة قريبة فقط.','تحقق من البحث المحدد والمكافأة والكلفة ونداء الضباط قبل التبرع.','تبرعات gold ليست إلزامية عند ضيق الموارد. لا تشتت التبرعات على فروع غير معتمدة.'],
  ['تعزيزات الوزير وCapitol','احصل على اللقب أو الـbuff قبل الضغط على Start. لا يقلل عادة مدة بحث أو بناء بدأ بالفعل.','اطلب Secretary of Science قبل بحث طويل وCo-Builder قبل البناء. مع Tech Centers اثنين جهز الطابورين لنافذة اللقب. إن Co-operative Research وResearch Now مهارتا Engineer ولهما مؤقتات.','تأكد من نشاط اللقب في ملفك ثم ابدأ. افحص وصف المهارة والمؤقت قبل Research Now.','لا تجمع النسب حسابيًا ببساطة، ولا تفترض أثرًا رجعيًا للقب المتأخر.']
]);

add('ko',[
  ['영웅 및 분대 배치','앞줄에 영웅 2명, 뒷줄에 3명을 둡니다. 같은 유형 5명은 Tank, Aircraft, Missile의 전체 보너스를 받습니다.','Tank: 앞 Murphy·Williams, 뒤 Kimberly·Stetmann·Marshall. Aircraft: 앞 Carlie·Lucius, 뒤 DVA·Morrison·Schuyler. Missile: 앞 Adam·McGregor, 뒤 Tesla·Fiona·Swift. Air > Tank > Missile > Air 상성입니다.','방어 영웅이 실제 앞줄에 보이는지 확인하세요. 실전 전투력과 buff도 비교해야 하며, 지나치게 약한 counter 분대는 질 수 있습니다.','배치만 따라 하려고 가장 잘 키운 분대를 해체하지 말고, 먼저 핵심 5명을 완성하세요.'],
  ["Drone Chips와 부품","Drone Chips, Drone Components, Drone Parts는 서로 다른 아이템입니다. 지원할 영웅 유형에 맞는 칩 세트를 고르세요.","UR 칩 4개 슬롯: Interference = Memory Ultra Fission, Defense = Gravitational Resonance Armor, Initial Move = Absolute Quantum Field, Attack = Lethal Firestorm. 첫 UR 세트는 이 순서로 제작하세요. Firestorm은 2성과 5성에서 공격 대상이 늘어납니다.","핵심 세트 하나를 균형 있게 완성하세요. 업그레이드 화면에서 역할, 영웅 유형, 별 효과, 재료 이름을 확인합니다.","Parts나 Components를 Chips로 혼동하거나 핵심 세트 전에 2군 세트를 올리지 마세요."],
  ['UR 장비와 Blueprints','핵심 5명의 금색 Legendary 장비를 먼저 40레벨로 만드세요. 여러 영웅에게 얇게 나누는 것보다 집중 투자가 좋습니다.','Kimberly·DVA·Tesla는 Railgun/Cannon 다음 Chip. Murphy·Williams·Lucius·Carlie는 Armor 다음 Radar. Legendary Blueprints는 별을 열고 Mythic Blueprints는 후반에 필요합니다.','다음 별의 요구량을 미리 확인하고, 유리하다면 큰 업그레이드를 점수 이벤트와 맞추세요.','Blueprint 수량은 별과 버전에 따라 다릅니다. 고정 수치를 믿거나 비싼 재료를 모든 분대에 흩뿌리지 마세요.'],
  ['상점 구매 우선순위','상점마다 화폐가 다릅니다. 병목을 해결하는 물품을 사고, F2P는 계획 없이 재고를 비우지 마세요.','VIP: 주간 Stamina, 필요한 speedups, 여유 있을 때 UR shards. Honor: 주로 Legendary Gear Blueprints를 위해 저장. Alliance: RZSN 토요일 규칙용 8h/24h shields를 항상 확보한 뒤 UR shards, Drone Parts, speedups. Campaign: 자원 상자, HQ30 근처에서는 특히 gold, Legendary Campaign chests, Drone Parts 또는 재고에 따른 universal EW shards.','구매 전 화폐 아이콘, 재고, reset을 확인하세요. 가격과 품목은 서버와 버전에 따라 다릅니다.','shield 비축분을 편의품에 쓰지 마세요. 여기서 정확한 가격을 보장하지 않습니다.'],
  ['폭포식 병력 훈련','여러 Barracks를 핵심 레벨에 유지해 점수 시간에 병력을 연쇄 승급합니다.','기준: Barracks 17에서 T6, 20에서 T7, 24에서 T8, 27에서 T9, 30과 Unit X로 T10. 17/20/24/27이면 주중 T6을 훈련하고 금요일 실시간 규칙이 승급을 채점할 때 T6 → T7 → T8 → T9로 올립니다.','시작 전 VS/이벤트 점수, 대기열, 시간, Drill Ground 용량을 확인하고 전체 연쇄용 공간을 남기세요.','승급 점수가 항상 4배인 것은 아닙니다. 오래된 계산기보다 현재 이벤트 화면을 따르세요.'],
  ["General's Trial","General's Trial에서는 해금된 최고 난이도를 선택하세요. 후반 적은 혼자 이기기 어려울 수 있지만 동맹의 도움을 받을 수 있습니다.","적이 너무 강하다면 동맹 채팅에서 도움을 요청하세요. 강한 RZSN 멤버가 Rally를 시작하거나 내 Rally에 참여해 함께 처치할 수 있습니다. 난이도와 적 레벨을 알려주세요.","버전 차이가 있으니 이벤트 화면에서 모드, 비용, 횟수, 보상, reset을 확인하세요. 모든 Trial이 R5 일정이라고 가정하지 말고 채팅으로 조율합니다.","혼자 이기기 어려운 적 하나 때문에 난이도를 낮추지 마세요. 먼저 Rally 지원을 요청하고 현재 이벤트 규칙을 확인하세요."],
  ['Zombie Siege','Zombie Siege는 일반적으로 20 wave입니다. shield는 이벤트 좀비를 막지 못하므로 Wall Defense와 지원이 핵심입니다.','벽에 알맞은 강한 방어 분대를 배치하세요. 후반 wave 전에는 강한 인원이 약한 기지를 지원하고 R4/R5에게 이벤트 레벨을 확인합니다.','wave, 벽 분대, 지원 수용량, 탈락 상태를 확인하세요. 탈락 뒤에는 그 회차에서 기지가 더 공격받지 않습니다.','실패 규칙은 출처와 버전마다 다릅니다. “실패 1회뿐”이라는 주장 대신 현재 규칙을 읽으세요.'],
  ["Marshal's Guard",'일반적으로 30분 동안 장갑 Tank boss 5명과 3분 rally로 피해를 겨루는 협동 이벤트입니다.','행군을 줄이려면 hive 가까이 있으세요. 가장 강한 적합 분대를 보내고, 참가 순서가 좋아지면 약한 인원이 시작할 수 있습니다. drill platform에 기부하고 대상 세트당 최대 5단계까지 장교 지시를 따릅니다.','실시간 시간과 rally 계획을 확인하세요. RZSN은 흔히 20:00 CET / 16:00 ST지만 최신 공지가 기준입니다.','평소 시간을 고정 일정으로 여기거나 계획 밖 rally로 피해를 나누지 마세요.'],
  ['Rally 및 전투 기본','rally는 모드마다 평가 방식이 다릅니다. 리더, buff, counter, 목표 허가를 모두 봐야 합니다.','infection이 있는 Season PvE에서는 rally leader의 resistance가 낮은 참가자를 보완할 수 있습니다. PvP는 실전 전투력, 유형 counter, 영웅/장비 buff, 편성을 비교합니다. stronghold는 승인된 리더만 시작합니다.','출정 전 목표, 리더, 참가 순서, 상성 순환, 활성 buff를 확인하세요. 토요일에는 필수 shield를 유지하고 우호 또는 미승인 목표를 공격하지 않습니다.','resistance는 PvP 전투력을 대신하지 않습니다. 잘못된 리더나 shield 해제는 연맹 전체에 피해를 줍니다.'],
  ['Desert Storm','지정된 조, 빠른 소통, 지속 점수로 이깁니다. 무작위 단독 teleport를 피하고 실제 참가 가능 여부로 reserve를 정하세요.','해당 지도라면 hospitals를 먼저 지키거나 빼앗고, refineries, Science Hub/Info Center, 개방 후 Nuclear Silo 같은 지속 점수원을 유지합니다. 조별로 시간차 teleport 후 지시된 목표로 이동하세요.','입장 전 역할, 조, reserve 상태, 현재 지도 목표를 확인하세요. 배치와 이름은 달라질 수 있습니다.','지원 없는 lane에 혼자 이동하거나 중요한 시설을 비운 채 kill만 쫓지 마세요.'],
  ['Alliance Tech와 기부 우선순위','Alliance Research 기부는 개인 Tech Center가 아니라 연맹 기술로 갑니다. R4/R5가 강조한 추천 항목에 기부하세요.','선호 기술 20% bonus가 활성화되면 이용하고 contribution points를 모읍니다. 초기 연맹은 Economy/Development, 성장한 RZSN은 Combat ATK·DEF·HP가 유리합니다. Territory는 임박한 필요에만 투자합니다.','기부 전 강조된 연구, bonus 상태, 비용, 최신 장교 지시를 확인하세요.','자원이 부족하면 gold 기부는 의무가 아닙니다. 승인되지 않은 가지에 분산하지 마세요.'],
  ['Minister / Capitol Buff','Start를 누르기 전에 title 또는 buff를 받으세요. 이미 시작한 연구나 건설에는 보통 소급 적용되지 않습니다.','긴 연구 전 Secretary of Science, 건설 전 Co-Builder를 요청합니다. Tech Center가 2개면 두 대기열을 title 시간에 맞춰 준비하세요. Co-operative Research와 Research Now는 Engineer skill이며 각 timer를 확인합니다.','프로필에서 title 활성화를 확인한 뒤 시작하세요. Research Now 전 설명과 활성 시간을 봅니다.','퍼센트를 단순 합산하거나 늦게 받은 title이 소급된다고 생각하지 마세요.']
]);

add('sv',[
  ['Hjältar och truppformationer','Placera två hjältar fram och tre bak. Fem av samma typ ger full bonus för Tank, Aircraft eller Missile.','Tank: Murphy och Williams fram; Kimberly, Stetmann, Marshall bak. Aircraft: Carlie och Lucius fram; DVA, Morrison, Schuyler bak. Missile: Adam och McGregor fram; Tesla, Fiona, Swift bak. Air slår Tank, Tank slår Missile, Missile slår Air.','Försvararna ska synas i främre raden. Jämför verklig styrka och buffs; en mycket svagare counter-trupp kan ändå förlora.','Bryt inte upp din bäst utvecklade trupp bara för att kopiera en formation. Färdigställ fem kärnhjältar först.'],
  ["Drone Chips och komponenter","Drone Chips, Drone Components och Drone Parts är olika föremål. Matcha chip-setet med rätt hjältyp.","Fyra UR-platser: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Tillverka första UR-setet i den ordningen. Firestorm träffar fler mål vid 2 och 5 stjärnor.","Levla ett komplett kärnset jämnt. Kontrollera roll, hjältyp, stjärnförhandsvisning och materialnamn i uppgraderingen.","Blanda inte ihop Parts eller Components med Chips och prioritera inte andra truppen före kärnsetet."],
  ['UR-utrustning och Blueprints','Ta först kärntruppens gyllene Legendary-utrustning till nivå 40. Koncentrerade resurser är bättre än tunn spridning.','Kimberly, DVA och Tesla: Railgun/Cannon, sedan Chip. Murphy, Williams, Lucius och Carlie: Armor, sedan Radar. Legendary Blueprints öppnar stjärnor; Mythic Blueprints kommer senare.','Kontrollera nästa stjärnkrav och tajma stora uppgraderingar med ett aktivt poängevent när det lönar sig.','Blueprint-behov ändras med stjärna och version. Lita inte på fasta totalsiffror och sprid inte dyrt material.'],
  ['Köpprioriteringar i butiker','Varje butik har egen valuta. Köp det som löser en flaskhals; F2P bör inte tömma hyllor utan plan.','VIP: veckovis Stamina, valda speedups och UR shards när du har råd. Honor: spara främst till Legendary Gear Blueprints. Alliance: reservera alltid 8h/24h shields för RZSN:s lördagsregel, därefter UR shards, Drone Parts och speedups. Campaign: resurslådor, särskilt gold nära HQ30, Legendary Campaign chests, Drone Parts eller universal EW shards efter lager.','Kontrollera valutasymbol, lager och reset. Priser och utbud kan skilja mellan servrar och versioner.','Använd aldrig shield-reserven till bekvämlighetsköp. Inget exakt pris garanteras här.'],
  ['Vattenfallsutbildning av trupper','Håll flera Barracks på viktiga nivåer så trupper kan befordras i en kedja under ett poängfönster.','Milstolpar: T6 vid Barracks 17, T7 vid 20, T8 vid 24, T9 vid 27, T10 vid 30 plus Unit X. Med 17/20/24/27 tränar du T6 under veckan och befordrar T6 → T7 → T8 → T9 på fredag om aktiva regler ger poäng.','Kontrollera VS-/eventpoäng, köer, tid och Drill Ground-kapacitet. Lämna plats för hela kedjan.','Befordran ger inte alltid fyra gånger poängen. Följ den aktiva eventskärmen, inte en gammal kalkylator.'],
  ["General's Trial","Välj den högsta upplåsta svårighetsgraden i General's Trial. Senare fiender kan vara för starka för en ensam spelare, men alliansen kan hjälpa.","Om en fiende är för stark, be om hjälp i allianschatten. Starkare RZSN-medlemmar kan starta ett rally eller gå med i ditt och besegra fienden tillsammans. Ange svårighetsgrad och fiendens nivå.","Kontrollera läge, kostnad, försök, belöningar och reset eftersom varianter finns. Samordna i chatten utan att anta ett R5-schema varje gång.","Sänk inte svårighetsgraden bara för att en fiende är för stark solo. Be först om rallyhjälp och kontrollera eventets regler."],
  ['Zombie Siege','Zombie Siege har vanligen 20 vågor. Shield stoppar inte eventets zombier; Wall Defense och förstärkning avgör.','Sätt en riktig stark försvarstrupp på muren. Starkare spelare förstärker svagare baser före sena vågor; fråga R4/R5 om eventnivån.','Följ vågor, murtrupper, förstärkningskapacitet och utslagning. Efter utslagning får basen inga fler attacker den omgången.','Reglerna för misslyckande varierar. Lita inte på ”bara ett misslyckande”; läs aktuella regler.'],
  ["Marshal's Guard",'Samordnat 30-minutersevent med fem bepansrade Tank-bossar och vanligen tre minuters rally.','Stanna nära hive för kortare marsch. Skicka starkaste lämpliga truppen; en svagare medlem kan starta för bättre anslutningsordning. Donera till drill platform och följ officerarnas prioriteringar, upp till fem faser per målset.','Kontrollera aktuell tid och plan. RZSN använder ofta 20:00 CET / 16:00 ST, men senaste meddelandet gäller.','Lås inte det vanliga klockslaget och dela inte skadan med oplanerade rallyn.'],
  ['Grunder för rally och strid','Rally bedöms olika i olika lägen. Ledare, buffs, counter och måltillstånd spelar roll.','I Season PvE med infection kan rally leaderns resistance täcka svagare deltagare. I PvP jämför du verklig styrka, typ-counter, hjälte-/utrustningsbuffs och uppställning. Endast godkänd ledare startar stronghold.','Kontrollera mål, ledare, deltagarordning, counter-cykel och buffs. På lördag behåller du krävt shield och angriper inga allierade eller otillåtna mål.','Resistance ersätter inte PvP-styrka. Fel ledare eller tappat shield skadar hela alliansen.'],
  ['Desert Storm','Vinn med tilldelade grupper, snabb kommunikation och stadiga poäng, inte slumpmässiga solo-teleports. Reserven ska följa verklig tillgänglighet.','Om kartan stöder det, skydda eller ta hospitals först och håll sedan refineries, Science Hub/Info Center och Nuclear Silo när den öppnar. Teleportera gruppvis i omgångar till utropat fokus.','Bekräfta roll, grupp, reservstatus och aktuella kartmål före start; kartan och namnen kan variera.','Teleportera inte ensam till en lane utan stöd och jaga inte kills medan viktiga byggnader lämnas tomma.'],
  ['Alliansteknik och donationer','Donationer till Alliance Research går till allianstekniken, inte ditt personliga Tech Center. Följ R4/R5:s markerade rekommendation.','Använd 20% bonus på föredragen forskning när den är aktiv och samla contribution points. Tidigt behövs ofta Economy/Development; moget RZSN tjänar mer på Combat ATK, DEF och HP. Territory endast inför nära behov.','Kontrollera markerad forskning, bonus, kostnad och officersbesked före donation.','Gold-donationer är inte obligatoriska vid resursbrist. Sprid inte donationer på ej godkända grenar.'],
  ['Minister- och Capitol-buffs','Få titeln eller buffen innan du trycker Start. Den kortar normalt inte redan påbörjad forskning eller byggnation.','Be om Secretary of Science före lång forskning och Co-Builder före byggande. Med två Tech Centers förbereder du båda köerna. Co-operative Research och Research Now är Engineer skills med aktiva timers.','Kontrollera titeln på profilen och starta sedan. Läs skillbeskrivning och timer före Research Now.','Addera inte procentsatser rakt av och anta inte retroaktiv effekt.']
]);

add('pt',[
  ['Heróis e formações de esquadrão','Coloca dois heróis na frente e três atrás. Cinco heróis do mesmo tipo dão o bônus completo de Tank, Aircraft ou Missile.','Tank: Murphy e Williams na frente; Kimberly, Stetmann, Marshall atrás. Aircraft: Carlie e Lucius na frente; DVA, Morrison, Schuyler atrás. Missile: Adam e McGregor na frente; Tesla, Fiona, Swift atrás. Air vence Tank, Tank vence Missile, Missile vence Air.','Os defensores devem aparecer na linha da frente. Compara poder real e buffs; um esquadrão counter muito mais fraco ainda pode perder.','Não desmanches a tua equipa mais desenvolvida só para copiar uma formação. Completa primeiro cinco heróis principais.'],
  ["Drone Chips e componentes","Drone Chips, Drone Components e Drone Parts são itens diferentes. Combina o conjunto de chips com o tipo de herói correto.","Quatro slots UR: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Cria o primeiro conjunto UR por esta ordem. Firestorm atinge mais alvos nas 2 e 5 estrelas.","Evolui um conjunto principal completo com equilíbrio. Confere função, tipo de herói, prévia da estrela e nome do material.","Não confundas Parts ou Components com Chips, nem priorizes o segundo esquadrão antes do principal."],
  ['Equipamento UR e Blueprints','Leva primeiro o equipamento Legendary dourado dos cinco heróis principais ao nível 40. Concentrar recursos supera distribuí-los.','Kimberly, DVA e Tesla: Railgun/Cannon e depois Chip. Murphy, Williams, Lucius e Carlie: Armor e depois Radar. Legendary Blueprints abrem estrelas; Mythic Blueprints vêm mais tarde.','Confere o requisito da próxima estrela e sincroniza melhorias grandes com um evento de pontos ativo quando compensar.','A quantidade de Blueprints muda com estrela e versão. Não confies em totais fixos nem espalhes materiais caros por todos.'],
  ['Prioridades de compra nas lojas','Cada loja usa a sua moeda. Compra para resolver um bloqueio; jogadores F2P não devem limpar as prateleiras sem plano.','VIP: Stamina semanal, speedups selecionados e UR shards quando houver folga. Honor: guarda sobretudo para Legendary Gear Blueprints. Alliance: reserva sempre shields de 8h/24h para a regra RZSN de sábado; depois UR shards, Drone Parts e speedups. Campaign: caixas de recursos, especialmente gold perto do HQ30, Legendary Campaign chests, Drone Parts ou universal EW shards conforme o estoque.','Confere moeda, estoque e reset. Preços e itens podem variar por servidor e versão.','Nunca gastes a reserva de shields em conveniência. Nenhum preço exato é garantido aqui.'],
  ['Treino de tropas em cascata','Mantém vários Barracks nos níveis-chave para promover tropas em cadeia durante uma janela de pontos.','Marcos: T6 no Barracks 17, T7 no 20, T8 no 24, T9 no 27 e T10 no 30 mais Unit X. Com 17/20/24/27, treina T6 durante a semana e promove T6 → T7 → T8 → T9 na sexta se as regras ativas pontuarem promoções.','Confere pontuação VS/evento, filas, tempo e capacidade do Drill Ground. Deixa espaço para toda a cadeia.','Promoção nem sempre vale quatro vezes. Segue a tela ativa do evento, não uma calculadora antiga.'],
  ["General's Trial","Escolhe a dificuldade mais alta já desbloqueada no General's Trial. Os inimigos seguintes podem ser fortes demais a solo, mas a aliança pode ajudar.","Se um inimigo for demasiado forte, pede ajuda no chat da aliança. Membros RZSN mais fortes podem iniciar uma rally ou juntar-se à tua para o derrotar em conjunto. Indica dificuldade e nível do inimigo.","Confere modo, custo, tentativas, recompensas e reset na interface, pois existem variantes. Coordena no chat sem supor agenda R5 em todo Trial.","Não reduzas a dificuldade por causa de um único inimigo demasiado forte. Pede primeiro apoio por rally e confere as regras atuais do evento."],
  ['Zombie Siege','Zombie Siege geralmente tem 20 ondas. Shield não para os zombies do evento; Wall Defense e reforços decidem.','Coloca uma equipa defensiva forte na muralha. Jogadores fortes reforçam bases fracas antes das ondas finais; pergunta a R4/R5 o nível do evento.','Acompanha ondas, equipas na muralha, capacidade de reforço e eliminação. Depois de eliminada, a base não recebe mais ataques nessa rodada.','As regras de falha variam por fonte e versão. Não dependas de “apenas uma falha”; lê as regras atuais.'],
  ["Marshal's Guard",'Evento coordenado de 30 minutos com cinco bosses Tank blindados e rallies de três minutos nas versões comuns.','Fica perto do hive para reduzir a marcha. Envia o esquadrão adequado mais forte; um membro fraco pode iniciar se melhorar a ordem de entrada. Doa para a drill platform e segue as prioridades dos oficiais, até cinco fases por conjunto.','Confere hora e plano ao vivo. RZSN usa muitas vezes 20:00 CET / 16:00 ST, mas o anúncio atual manda.','Não fixes o horário habitual nem dividas o dano com rallies fora do plano.'],
  ['Fundamentos de rally e combate','Rally não é calculada da mesma forma em todos os modos. Líder, buffs, counter e autorização do alvo importam.','No PvE Season com infection, a resistance do rally leader pode cobrir participantes menores. No PvP compara poder real, counter de tipo, buffs de herói/equipamento e formação. Só um líder autorizado inicia stronghold.','Antes de marchar, confere alvo, líder, ordem, ciclo counter e buffs. No sábado mantém o shield exigido e não ataca aliados ou alvos sem autorização.','Resistance não substitui força PvP. Líder errado ou shield perdido prejudica toda a aliança.'],
  ['Desert Storm','Vence com grupos definidos, comunicação rápida e pontos contínuos, não com teleports solo aleatórios. Reserva depende da disponibilidade real.','Quando houver no mapa, protege ou disputa hospitals primeiro; depois segura refineries, Science Hub/Info Center e Nuclear Silo quando abrir. Faz teleport em grupos escalonados para o foco indicado.','Confirma função, grupo, reserva e objetivos atuais antes de entrar; mapa e nomes podem variar.','Não faças teleport sozinho para uma rota sem apoio nem persigas kills deixando estruturas vazias.'],
  ['Tech da aliança e prioridades de doação','Doações de Alliance Research vão para a tecnologia da aliança, não para o teu Tech Center. Segue a recomendação destacada por R4/R5.','Usa o bônus de 20% da pesquisa preferida quando ativo e ganha contribution points. No início, Economy/Development; num RZSN maduro, Combat ATK, DEF e HP. Territory só para necessidade próxima.','Confere pesquisa destacada, bônus, custo e instrução atual dos oficiais antes de doar.','Doações em gold não são obrigatórias se faltarem recursos. Não espalhes contribuições por ramos não aprovados.'],
  ['Buffs de Minister e Capitol','Recebe o título ou buff antes de tocar em Start. Normalmente não reduz pesquisa ou construção já iniciada.','Pede Secretary of Science antes de pesquisa longa e Co-Builder antes de construir. Com dois Tech Centers prepara as duas filas. Co-operative Research e Research Now são skills Engineer com timers próprios.','Confirma o título ativo no perfil e só então inicia. Vê descrição e timer antes de Research Now.','Não somes percentagens de forma simples nem assumes efeito retroativo.']
]);

add('nl',[
  ['Helden en squadformaties','Zet twee helden voor en drie achter. Vijf helden van hetzelfde type geven de volledige Tank-, Aircraft- of Missile-bonus.','Tank: Murphy en Williams voor; Kimberly, Stetmann, Marshall achter. Aircraft: Carlie en Lucius voor; DVA, Morrison, Schuyler achter. Missile: Adam en McGregor voor; Tesla, Fiona, Swift achter. Air verslaat Tank, Tank verslaat Missile, Missile verslaat Air.','Verdedigers moeten zichtbaar vooraan staan. Vergelijk echte squadkracht en buffs; een veel zwakkere counter-squad kan nog steeds verliezen.','Breek je best ontwikkelde squad niet af om een formatie te kopiëren. Bouw eerst vijf kernhelden af.'],
  ["Drone Chips en componenten","Drone Chips, Drone Components en Drone Parts zijn verschillende items. Koppel de chipset aan het juiste heldentype.","De vier UR-slots: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Maak je eerste UR-set in die volgorde. Firestorm raakt op 2 en 5 sterren meer doelen.","Level één complete kernset evenwichtig. Controleer rol, heldentype, stervoorbeeld en materiaalnaam in het upgradescherm.","Verwar Parts of Components niet met Chips en investeer niet eerst in de tweede squad."],
  ['UR-uitrusting en Blueprints','Breng eerst de gouden Legendary-uitrusting van je vijf kernhelden naar level 40. Gerichte investering is sterker dan spreiding.','Kimberly, DVA en Tesla: Railgun/Cannon, daarna Chip. Murphy, Williams, Lucius en Carlie: Armor, daarna Radar. Legendary Blueprints openen sterren; Mythic Blueprints komen later.','Controleer de vereisten voor de volgende ster en plan grote upgrades zo nodig tijdens een actief puntenevent.','Blueprint-behoeften verschillen per ster en versie. Vertrouw geen vaste totalen en verspreid dure materialen niet over alle squads.'],
  ['Koopprioriteiten per winkel','Elke winkel gebruikt eigen valuta. Koop wat een knelpunt oplost; F2P-spelers hoeven geen schappen leeg te kopen.','VIP: wekelijkse Stamina, nuttige speedups en UR shards als je rijk genoeg bent. Honor: vooral sparen voor Legendary Gear Blueprints. Alliance: reserveer altijd 8h/24h shields voor het RZSN-zaterdagbeleid, daarna UR shards, Drone Parts en speedups. Campaign: grondstofkisten, vooral gold rond HQ30, Legendary Campaign chests, Drone Parts of universal EW shards naar voorraad.','Controleer valuta-icoon, voorraad en reset. Prijzen en aanbod kunnen per server en versie verschillen.','Gebruik de shield-reserve nooit voor gemaksaankopen. Exacte prijzen zijn hier niet gegarandeerd.'],
  ['Watervaltraining voor troepen','Houd meerdere Barracks op belangrijke levels om troepen tijdens een puntenvenster achter elkaar te promoveren.','Mijlpalen: T6 op Barracks 17, T7 op 20, T8 op 24, T9 op 27 en T10 op 30 plus Unit X. Met 17/20/24/27 train je doordeweeks T6 en promoveer je vrijdag T6 → T7 → T8 → T9 als de actuele regels promoties belonen.','Controleer VS-/eventscore, wachtrijen, duur en Drill Ground-capaciteit. Houd ruimte voor de hele keten.','Promoties geven niet altijd vier keer score. Volg het live eventscherm, niet een oude calculator.'],
  ["General's Trial","Kies de hoogste ontgrendelde moeilijkheidsgraad in General's Trial. Latere vijanden kunnen te sterk zijn voor solo, maar je alliantie kan helpen.","Is een vijand te sterk, vraag dan hulp in de alliantiechat. Sterkere RZSN-leden kunnen een rally starten of zich bij jouw rally aansluiten om samen te winnen. Vermeld moeilijkheid en vijandniveau.","Controleer modus, kosten, pogingen, beloningen en reset omdat varianten bestaan. Stem af in de chat; verwacht niet elke keer een R5-schema.","Verlaag de moeilijkheid niet omdat één vijand solo te sterk is. Vraag eerst rallyhulp en controleer de actuele eventregels."],
  ['Zombie Siege','Zombie Siege heeft doorgaans 20 waves. Shield stopt eventzombies niet; Wall Defense en versterking bepalen de uitkomst.','Zet een passende sterke verdedigingssquad op de muur. Sterkere spelers versterken zwakkere bases vóór late waves; vraag R4/R5 naar het eventlevel.','Volg waves, muursquads, versterkingscapaciteit en uitschakeling. Na uitschakeling krijgt de basis die ronde geen aanvallen meer.','Faallogica verschilt per bron en versie. Vertrouw niet op “maar één fout”; lees de actuele regels.'],
  ["Marshal's Guard",'Gecoördineerd event van 30 minuten met vijf gepantserde Tank-bosses en meestal rally’s van drie minuten.','Blijf bij de hive voor kortere mars. Stuur je sterkste geschikte squad; een zwakker lid kan starten voor een betere instapvolgorde. Doneer aan het drill platform en volg officiersprioriteiten, maximaal vijf fases per doelset.','Controleer live tijd en plan. RZSN gebruikt vaak 20:00 CET / 16:00 ST, maar de actuele aankondiging is leidend.','Maak van de gebruikelijke tijd geen vaste afspraak en verdeel schade niet met ongeplande rally’s.'],
  ['Basis van rally en gevecht','Een rally wordt niet in elke modus hetzelfde beoordeeld. Leider, buffs, counter en doeltoestemming zijn belangrijk.','In Season PvE met infection kan de resistance van de rally leader lagere deelnemers dekken. In PvP vergelijk je werkelijke kracht, type-counter, held-/uitrustingsbuffs en opstelling. Alleen een bevoegde leider start strongholds.','Controleer doel, leider, deelnemersvolgorde, countercyclus en buffs. Houd zaterdag het vereiste shield en val geen bondgenoten of ongeoorloofde doelen aan.','Resistance vervangt geen PvP-kracht. Een verkeerde leider of verloren shield schaadt de hele alliantie.'],
  ['Desert Storm','Win met toegewezen groepen, snelle communicatie en constante punten, niet met willekeurige solo-teleports. Reserve volgt echte beschikbaarheid.','Als de kaart ze heeft, bescherm of betwist eerst hospitals; houd daarna refineries, Science Hub/Info Center en Nuclear Silo zodra die opent. Teleporteer gefaseerd per groep naar de afgeroepen focus.','Bevestig rol, groep, reservestatus en actuele kaartdoelen vóór binnenkomst; indeling en namen kunnen verschillen.','Teleporteer niet alleen naar een lane zonder steun en jaag niet op kills terwijl structuren onbezet zijn.'],
  ['Alliantietechniek en donaties','Donaties aan Alliance Research gaan naar alliantietechniek, niet naar je persoonlijke Tech Center. Volg de gemarkeerde R4/R5-aanbeveling.','Gebruik de 20% bonus voor preferred tech wanneer actief en verzamel contribution points. Vroeg helpt Economy/Development; volwassen RZSN profiteert meer van Combat ATK, DEF en HP. Territory alleen voor nabije behoefte.','Controleer gemarkeerd onderzoek, bonus, kosten en actuele officiersoproep vóór donatie.','Gold-donaties zijn niet verplicht bij schaarse middelen. Verspreid bijdragen niet over niet-goedgekeurde takken.'],
  ['Minister- en Capitol-buffs','Ontvang titel of buff vóór je op Start drukt. Lopend onderzoek of bouw wordt normaal niet achteraf verkort.','Vraag Secretary of Science vóór lang onderzoek en Co-Builder vóór bouwen. Bereid met twee Tech Centers beide wachtrijen voor. Co-operative Research en Research Now zijn Engineer skills met timers.','Controleer de actieve titel op je profiel en start dan. Lees beschrijving en timer vóór Research Now.','Tel percentages niet simpel op en neem geen terugwerkende kracht aan.']
]);

add('th',[
  ['ฮีโร่และการจัดทีม','วางฮีโร่สองตัวแถวหน้าและสามตัวแถวหลัง ฮีโร่ประเภทเดียวกันครบห้าตัวจะได้โบนัส Tank, Aircraft หรือ Missile เต็มรูปแบบ','Tank: หน้า Murphy, Williams; หลัง Kimberly, Stetmann, Marshall. Aircraft: หน้า Carlie, Lucius; หลัง DVA, Morrison, Schuyler. Missile: หน้า Adam, McGregor; หลัง Tesla, Fiona, Swift. Air ชนะ Tank, Tank ชนะ Missile, Missile ชนะ Air','ให้ตัวป้องกันอยู่ในแถวหน้าที่มองเห็นจริง เปรียบเทียบพลังและ buffs ด้วย เพราะทีม counter ที่อ่อนกว่ามากยังแพ้ได้','อย่ารื้อทีมที่พัฒนาดีที่สุดเพียงเพื่อเลียนแบบรูปแบบ สร้างทีมหลักห้าตัวให้เสร็จก่อน'],
  ["Drone Chips และส่วนประกอบ","Drone Chips, Drone Components และ Drone Parts เป็นคนละไอเทม เลือกชุดชิปให้ตรงกับประเภทฮีโร่","ช่อง UR ทั้งสี่: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm สร้างเซต UR แรกตามลำดับนี้ Firestorm ที่ 2 และ 5 ดาวโจมตีเป้าหมายได้มากขึ้น","อัปชุดหลักหนึ่งชุดให้ครบและสมดุล ตรวจหน้าจออัปเกรดว่าหน้าที่ ประเภทฮีโร่ เอฟเฟกต์ดาว และชื่อวัสดุถูกต้อง","อย่าสับสน Parts หรือ Components กับ Chips และอย่าลงชุดทีมสองก่อนทีมหลัก"],
  ['อุปกรณ์ UR และ Blueprints','ยกระดับอุปกรณ์ Legendary สีทองของฮีโร่หลักห้าตัวถึงเลเวล 40 ก่อน การทุ่มให้ทีมหลักดีกว่ากระจายบาง ๆ','Kimberly, DVA, Tesla: Railgun/Cannon ก่อน Chip. Murphy, Williams, Lucius, Carlie: Armor ก่อน Radar. Legendary Blueprints ใช้เปิดดาว ส่วน Mythic Blueprints ใช้ภายหลัง','ดูตัวอย่างความต้องการดาวถัดไป และทำอัปเกรดใหญ่ในอีเวนต์คะแนนเมื่อคุ้มค่า','จำนวน Blueprints เปลี่ยนตามดาวและเวอร์ชัน อย่าเชื่อยอดตายตัวหรือกระจายวัสดุแพงทุกทีม'],
  ['ลำดับซื้อของในร้าน','แต่ละร้านใช้สกุลเงินต่างกัน ซื้อของที่แก้คอขวด ผู้เล่น F2P ไม่ควรกวาดร้านโดยไม่มีแผน','VIP: Stamina รายสัปดาห์ speedups ที่จำเป็น และ UR shards เมื่อมีเหลือ Honor: เก็บหลัก ๆ เพื่อ Legendary Gear Blueprints. Alliance: สำรอง shields 8h/24h สำหรับกฎวันเสาร์ของ RZSN เสมอ แล้วจึง UR shards, Drone Parts, speedups. Campaign: กล่องทรัพยากร โดยเฉพาะ gold ใกล้ HQ30, Legendary Campaign chests, Drone Parts หรือ universal EW shards ตามสต็อก','ก่อนซื้อให้ดูไอคอนเงิน สต็อก และเวลา reset ราคาและของขายอาจต่างกันตามเซิร์ฟเวอร์และเวอร์ชัน','ห้ามใช้เงินสำรอง shields ซื้อของสะดวกสบาย และไม่มีราคาตายตัวที่รับรองไว้ที่นี่'],
  ['ฝึกทหารแบบน้ำตก','คง Barracks หลายแห่งไว้ที่เลเวลสำคัญ เพื่อเลื่อนขั้นทหารต่อเนื่องในช่วงทำคะแนน','จุดสำคัญ: T6 ที่ Barracks 17, T7 ที่ 20, T8 ที่ 24, T9 ที่ 27, T10 ที่ 30 พร้อม Unit X. ถ้ามี 17/20/24/27 ให้ฝึก T6 ระหว่างสัปดาห์ แล้วเลื่อน T6 → T7 → T8 → T9 วันศุกร์เมื่อกติกาปัจจุบันให้คะแนน','ตรวจคะแนน VS/อีเวนต์ คิว เวลา และความจุ Drill Ground ก่อนเริ่ม และเว้นที่สำหรับทั้งสาย','การเลื่อนขั้นไม่ได้คะแนนสี่เท่าเสมอ ให้ยึดหน้ากิจกรรมสด ไม่ใช่เครื่องคำนวณเก่า'],
  ["General's Trial","เลือกความยากสูงสุดที่ปลดล็อกแล้วใน General's Trial ศัตรูช่วงหลังอาจแข็งแกร่งเกินกว่าจะสู้คนเดียว แต่พันธมิตรช่วยได้","หากศัตรูแข็งแกร่งเกินไป ให้ขอความช่วยเหลือในแชตพันธมิตร สมาชิก RZSN ที่แข็งแกร่งกว่าสามารถเริ่ม Rally หรือเข้าร่วม Rally ของคุณเพื่อช่วยกำจัดศัตรู บอกระดับความยากและเลเวลศัตรูด้วย","ตรวจโหมด ค่าใช้จ่าย จำนวนครั้ง รางวัล และ reset ในหน้ากิจกรรม เพราะแต่ละเวอร์ชันต่างกัน ประสานในแชตโดยไม่สมมติว่า R5 จัดทุกครั้ง","อย่าลดความยากเพียงเพราะสู้ศัตรูตัวเดียวไม่ไหว ให้ขอความช่วยเหลือผ่าน Rally ก่อนและตรวจสอบกติกาอีเวนต์"],
  ['Zombie Siege','Zombie Siege โดยทั่วไปมี 20 wave และ shield ไม่หยุดซอมบี้กิจกรรม ต้องพึ่ง Wall Defense และการเสริมกำลัง','ตั้งทีมป้องกันที่แข็งแรงบนกำแพง ผู้เล่นเก่งเสริมฐานที่อ่อนก่อน wave ท้าย และถาม R4/R5 เรื่องระดับกิจกรรม','เฝ้าดู wave ทีมบนกำแพง ความจุ reinforcement และสถานะตกรอบ เมื่อตกรอบแล้วฐานจะไม่ถูกโจมตีต่อในรอบนั้น','กติกาความพ่ายแพ้ต่างกันตามแหล่งและเวอร์ชัน อย่าเชื่อว่า “พลาดได้ครั้งเดียว” ให้ดูข้อกำหนดสด'],
  ["Marshal's Guard",'อีเวนต์ทำ damage ร่วมกัน 30 นาที มี boss Tank หุ้มเกราะห้าตัวและ rally สามนาทีในเวอร์ชันทั่วไป','อยู่ใกล้ hive เพื่อลดเวลา march ส่งทีมที่เหมาะและแข็งที่สุด สมาชิกที่อ่อนกว่าอาจเริ่มเพื่อจัดลำดับ join ให้ดี บริจาค drill platform และทำตาม officer สูงสุดห้าเฟสต่อชุดเป้าหมาย','ตรวจเวลาจริงและแผน rally โดย RZSN มักใช้ 20:00 CET / 16:00 ST แต่ประกาศล่าสุดเป็นหลัก','อย่ายึดเวลาปกติเป็นตารางถาวร และอย่าแยก damage ด้วย rally นอกแผน'],
  ['พื้นฐาน Rally และการต่อสู้','แต่ละโหมดคำนวณ rally ต่างกัน ต้องดู leader, buffs, counter และสิทธิ์โจมตีเป้าหมาย','ใน Season PvE ที่มี infection ค่า resistance ของ rally leader อาจช่วยผู้เข้าร่วมที่ต่ำกว่า ส่วน PvP ต้องเทียบพลังจริง ประเภท counter, buffs ฮีโร่/อุปกรณ์ และการจัดทีม stronghold ให้ leader ที่ได้รับอนุญาตเริ่มเท่านั้น','ก่อน march ตรวจเป้าหมาย leader ลำดับผู้เข้าร่วม วงจร counter และ buffs วันเสาร์รักษา shield ที่กำหนดและห้ามโจมตีพันธมิตรหรือเป้าหมายไม่ได้รับอนุญาต','resistance ไม่แทนพลัง PvP เลือก leader ผิดหรือ shield หลุดทำให้ทั้งพันธมิตรเสียหาย'],
  ['Desert Storm','ชนะด้วยการแบ่งบทบาท การสื่อสารเร็ว และคะแนนต่อเนื่อง ไม่ใช่ teleport เดี่ยวแบบสุ่ม จัด reserve ตามเวลาที่มาได้จริง','ถ้าแผนที่มี ให้ป้องกันหรือแย่ง hospitals ก่อน แล้วคุม refineries, Science Hub/Info Center และ Nuclear Silo เมื่อเปิด teleport เป็นกลุ่มแบบเหลื่อมเวลาไปยังจุดที่เรียก','ก่อนเข้าให้ยืนยันบทบาท กลุ่ม สถานะ reserve และเป้าหมายแผนที่ปัจจุบัน เพราะผังและชื่ออาจเปลี่ยน','อย่า teleport คนเดียวไปเลนไร้การสนับสนุน หรือไล่ kill จนทิ้งสิ่งปลูกสร้างสำคัญ'],
  ['Alliance Tech และลำดับบริจาค','การบริจาค Alliance Research ไปยังเทคโนโลยีพันธมิตร ไม่ใช่ Tech Center ส่วนตัว ให้บริจาคหัวข้อที่ R4/R5 ไฮไลต์','ใช้โบนัส preferred tech 20% เมื่อเปิดและเก็บ contribution points พันธมิตรช่วงต้นมักเน้น Economy/Development ส่วน RZSN ที่พัฒนาแล้วเน้น Combat ATK, DEF, HP และ Territory เฉพาะเรื่องใกล้ใช้','ก่อนบริจาคตรวจหัวข้อที่ไฮไลต์ โบนัส ค่าใช้จ่าย และคำสั่ง officer ล่าสุด','ถ้าทรัพยากรตึง การบริจาค gold ไม่ใช่ข้อบังคับ และอย่ากระจายไปสาขาที่ยังไม่อนุมัติ'],
  ['Minister / Capitol Buffs','รับ title หรือ buff ก่อนกด Start โดยทั่วไปจะไม่ลดเวลางานวิจัยหรือก่อสร้างที่เริ่มไปแล้ว','ขอ Secretary of Science ก่อนวิจัยยาว และ Co-Builder ก่อนก่อสร้าง ถ้ามีสอง Tech Centers ให้เตรียมทั้งสองคิว Co-operative Research และ Research Now เป็น skill Engineer ที่มี timer','ยืนยัน title ว่าเปิดบนโปรไฟล์แล้วจึงเริ่ม ตรวจคำอธิบาย skill และ timer ก่อนใช้ Research Now','อย่าบวกเปอร์เซ็นต์ตรง ๆ หรือคิดว่า title ที่ได้ทีหลังจะย้อนหลัง'],
]);

add('km',[
  ['វីរបុរស និងការរៀបក្រុម','ដាក់វីរបុរសពីរនាក់នៅជួរមុខ និងបីនាក់នៅជួរក្រោយ។ វីរបុរសប្រភេទដូចគ្នាប្រាំនាក់ផ្តល់ bonus Tank, Aircraft ឬ Missile ពេញ។','Tank: Murphy និង Williams ខាងមុខ; Kimberly, Stetmann, Marshall ខាងក្រោយ។ Aircraft: Carlie និង Lucius ខាងមុខ; DVA, Morrison, Schuyler ខាងក្រោយ។ Missile: Adam និង McGregor ខាងមុខ; Tesla, Fiona, Swift ខាងក្រោយ។ Air ឈ្នះ Tank, Tank ឈ្នះ Missile, Missile ឈ្នះ Air។','ធានាថាអ្នកការពារស្ថិតនៅជួរមុខដែលមើលឃើញ។ ប្រៀបធៀបកម្លាំងពិត និង buffs ព្រោះក្រុម counter ខ្សោយខ្លាំងនៅតែអាចចាញ់។','កុំបំបែកក្រុមខ្លាំងបំផុតដើម្បីចម្លងទម្រង់។ បង្កើតក្រុមស្នូលប្រាំនាក់ជាមុន។'],
  ["Drone Chips និងសមាសធាតុ","Drone Chips, Drone Components និង Drone Parts ជាវត្ថុផ្សេងគ្នា។ ផ្គូផ្គង chip set តាមប្រភេទវីរបុរស។","រន្ធ UR ទាំងបួន៖ Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm។ ផលិតឈុត UR ដំបូងតាមលំដាប់នេះ។ Firestorm ផ្កាយ 2 និង 5 វាយគោលដៅបានច្រើនជាងមុន។","ដំឡើង set ស្នូលមួយឱ្យពេញនិងមានតុល្យភាព។ ពិនិត្យតួនាទី ប្រភេទវីរបុរស ផ្កាយ និងឈ្មោះសម្ភារៈ។","កុំច្រឡំ Parts ឬ Components ជាមួយ Chips និងកុំអាប់ក្រុមទីពីរមុនក្រុមស្នូល។"],
  ['UR Gear និង Blueprints','អាប់ Legendary gear ពណ៌មាស level 40 សម្រាប់វីរបុរសស្នូលប្រាំនាក់ជាមុន។ ការផ្តោតធនធានល្អជាងការចែកស្តើង។','Kimberly, DVA, Tesla: Railgun/Cannon មុន Chip។ Murphy, Williams, Lucius, Carlie: Armor មុន Radar។ Legendary Blueprints បើកផ្កាយ; Mythic Blueprints ប្រើពេលក្រោយ។','ពិនិត្យតម្រូវការផ្កាយបន្ទាប់ ហើយធ្វើ upgrade ធំពេល event ពិន្ទុសកម្មបើមានប្រយោជន៍។','ចំនួន Blueprints ប្រែតាមផ្កាយ និង version។ កុំជឿចំនួនថេរ ឬចែកសម្ភារៈថ្លៃទៅគ្រប់ក្រុម។'],
  ['អាទិភាពទិញក្នុងហាង','ហាងនីមួយៗប្រើរូបិយប័ណ្ណផ្សេង។ ទិញអ្វីដែលដោះស្រាយកង្វះ; F2P មិនគួរទិញអស់ដោយគ្មានផែនការ។','VIP: Stamina ប្រចាំសប្តាហ៍ speedups ចាំបាច់ និង UR shards ពេលមានសល់។ Honor: សន្សំសម្រាប់ Legendary Gear Blueprints។ Alliance: ទុក shields 8h/24h សម្រាប់គោលការណ៍ថ្ងៃសៅរ៍ RZSN ជានិច្ច បន្ទាប់មក UR shards, Drone Parts និង speedups។ Campaign: ប្រអប់ធនធាន ជាពិសេស gold ជិត HQ30, Legendary Campaign chests, Drone Parts ឬ universal EW shards តាម stock។','ពិនិត្យរូបិយប័ណ្ណ stock និង reset មុនទិញ។ តម្លៃនិងទំនិញអាចខុសតាម server និង version។','កុំចំណាយទុន shields លើវត្ថុងាយស្រួល។ គ្មានតម្លៃថេរណាមួយត្រូវបានធានា។'],
  ['ហ្វឹកហាត់ទ័ពបែប Waterfall','រក្សា Barracks ច្រើននៅ level សំខាន់ ដើម្បី promote ទ័ពជាបន្តបន្ទាប់ក្នុងពេលបានពិន្ទុ។','កម្រិត: T6 នៅ Barracks 17, T7 នៅ 20, T8 នៅ 24, T9 នៅ 27, T10 នៅ 30 បូក Unit X។ បើមាន 17/20/24/27 ហ្វឹក T6 ក្នុងសប្តាហ៍ ហើយ promote T6 → T7 → T8 → T9 ថ្ងៃសុក្រ បើច្បាប់បច្ចុប្បន្នផ្តល់ពិន្ទុ។','ពិនិត្យពិន្ទុ VS/event ជួរ ពេលវេលា និងសមត្ថភាព Drill Ground។ ទុកកន្លែងសម្រាប់ខ្សែទាំងមូល។','Promotion មិនតែងតែបានពិន្ទុបួនដងទេ។ អនុវត្តតាមអេក្រង់ event បច្ចុប្បន្ន។'],
  ["General's Trial","ជ្រើសរើសកម្រិតលំបាកខ្ពស់បំផុតដែលបានដោះសោក្នុង General's Trial។ សត្រូវចុងក្រោយអាចខ្លាំងពេកសម្រាប់វាយតែម្នាក់ឯង ប៉ុន្តែសម្ព័ន្ធអាចជួយបាន។","បើសត្រូវខ្លាំងពេក សុំជំនួយក្នុង Alliance Chat។ សមាជិក RZSN ដែលខ្លាំងអាចចាប់ផ្តើម Rally ឬចូលរួម Rally របស់អ្នក ដើម្បីកម្ចាត់សត្រូវជាមួយគ្នា។ ប្រាប់កម្រិតលំបាក និង Level សត្រូវ។","ពិនិត្យ mode ថ្លៃ ចំនួនដង រង្វាន់ និង reset ក្នុង event ព្រោះ version ខុសគ្នា។ សម្របសម្រួលក្នុង chat មិនសន្មតថា R5 រៀបចំគ្រប់ដង។","កុំបន្ថយកម្រិតលំបាកដោយសារសត្រូវមួយខ្លាំងពេក។ សុំជំនួយ Rally ជាមុន ហើយពិនិត្យច្បាប់ Event ក្នុងហ្គេម។"],
  ['Zombie Siege','Zombie Siege ជាទូទៅមាន 20 waves។ Shield មិនបញ្ឈប់ zombie event ទេ; Wall Defense និង reinforcement ជាអ្នកសម្រេច។','ដាក់ក្រុមការពារខ្លាំងលើ wall។ អ្នកខ្លាំង reinforce មូលដ្ឋានខ្សោយមុន wave ចុងក្រោយ ហើយសួរ R4/R5 អំពី event level។','មើល wave ក្រុម wall សមត្ថភាព reinforcement និងស្ថានភាពចាញ់។ ក្រោយចាញ់ មូលដ្ឋានមិនទទួលការវាយទៀតក្នុងជុំនោះ។','ច្បាប់បរាជ័យខុសតាមប្រភពនិង version។ កុំជឿថា «បរាជ័យតែមួយ»; អានច្បាប់បច្ចុប្បន្ន។'],
  ["Marshal's Guard",'Event damage រួម 30 នាទី មាន boss Tank ពាសដែកប្រាំ និង rally បីនាទីជាទូទៅ។','នៅជិត hive ដើម្បីកាត់ march។ ផ្ញើក្រុមខ្លាំងសមស្រប; សមាជិកខ្សោយអាចចាប់ផ្តើមដើម្បីលំដាប់ join ល្អ។ Donate drill platform និងធ្វើតាម officer រហូតដល់ប្រាំ phase ក្នុងមួយគោលដៅ។','ពិនិត្យម៉ោងនិងផែនការផ្ទាល់។ RZSN ប្រើ 20:00 CET / 16:00 ST ញឹកញាប់ ប៉ុន្តែសេចក្តីប្រកាសថ្មីជាគោល។','កុំកំណត់ម៉ោងធម្មតាជាអចិន្ត្រៃយ៍ និងកុំបំបែក damage ដោយ rally ក្រៅផែនការ។'],
  ['មូលដ្ឋាន Rally និងប្រយុទ្ធ','Rally ត្រូវបានគណនាខុសតាម mode។ Leader, buffs, counter និងការអនុញ្ញាតគោលដៅសំខាន់។','ក្នុង Season PvE មាន infection, resistance របស់ rally leader អាចគាំទ្រអ្នកទាប។ ក្នុង PvP ប្រៀបធៀបកម្លាំងពិត type counter, hero/gear buffs និងការរៀបក្រុម។ Stronghold ចាប់ផ្តើមដោយ leader អនុញ្ញាតប៉ុណ្ណោះ។','មុន march ពិនិត្យគោលដៅ leader លំដាប់អ្នកចូល counter និង buffs។ ថ្ងៃសៅរ៍រក្សា shield និងកុំវាយសម្ព័ន្ធមិត្ត ឬគោលដៅមិនអនុញ្ញាត។','Resistance មិនជំនួសកម្លាំង PvP។ Leader ខុស ឬ shield ដាច់ ប៉ះពាល់សម្ព័ន្ធទាំងមូល។'],
  ['Desert Storm','ឈ្នះដោយក្រុមដែលបានកំណត់ ការទាក់ទងរហ័ស និងពិន្ទុបន្ត មិនមែន teleport ម្នាក់ឯង។ Reserve តាមពេលទំនេរពិត។','បើមានលើផែនទី ការពារ ឬដណ្តើម hospitals មុន បន្ទាប់មកកាន់ refineries, Science Hub/Info Center និង Nuclear Silo ពេលបើក។ Teleport ជាក្រុមបន្តបន្ទាប់ទៅ focus ដែលបានហៅ។','មុនចូល បញ្ជាក់តួនាទី ក្រុម reserve និងគោលដៅផែនទី; ទម្រង់និងឈ្មោះអាចប្រែ។','កុំ teleport ម្នាក់ឯងទៅ lane គ្មានជំនួយ ឬដេញ kills ហើយទុកអគារសំខាន់។'],
  ['Alliance Tech និងអាទិភាព Donate','Donate Alliance Research ទៅ technology សម្ព័ន្ធ មិនមែន Tech Center ផ្ទាល់ខ្លួន។ Donate តាមការណែនាំ R4/R5 ដែលបាន highlight។','ប្រើ bonus 20% preferred tech ពេលសកម្ម និងយក contribution points។ សម្ព័ន្ធដំបូងផ្តោត Economy/Development; RZSN ចាស់ទុំផ្តោត Combat ATK, DEF, HP។ Territory តែពេលត្រូវការឆាប់ៗ។','ពិនិត្យ research ដែល highlight, bonus, តម្លៃ និងការណែនាំ officer មុន donate។','Gold donate មិនបង្ខំពេលធនធានតិច។ កុំបំបែកទៅ branch មិនអនុម័ត។'],
  ['Minister / Capitol Buffs','ទទួល title ឬ buff មុនចុច Start។ វាមិនកាត់ពេល research ឬ build ដែលបានចាប់ផ្តើមរួចជាទូទៅទេ។','សុំ Secretary of Science មុន research យូរ និង Co-Builder មុន build។ បើមាន Tech Centers ពីរ ត្រៀម queue ទាំងពីរ។ Co-operative Research និង Research Now ជា Engineer skills មាន timer។','បញ្ជាក់ title សកម្មលើ profile ហើយទើបចាប់ផ្តើម។ ពិនិត្យ skill និង timer មុន Research Now។','កុំបូកភាគរយត្រង់ៗ ឬសន្មតថា title យឺតមានប្រសិទ្ធភាពត្រឡប់ក្រោយ។']
]);

add('fil',[
  ['Mga hero at squad formation','Maglagay ng dalawang hero sa harap at tatlo sa likod. Limang hero ng iisang uri ang nagbibigay ng buong Tank, Aircraft, o Missile bonus.','Tank: Murphy at Williams sa harap; Kimberly, Stetmann, Marshall sa likod. Aircraft: Carlie at Lucius sa harap; DVA, Morrison, Schuyler sa likod. Missile: Adam at McGregor sa harap; Tesla, Fiona, Swift sa likod. Air laban sa Tank, Tank laban sa Missile, Missile laban sa Air.','Tiyaking nasa nakikitang front row ang defenders. Ihambing ang aktuwal na lakas at buffs; maaari pa ring matalo ang sobrang mahinang counter squad.','Huwag sirain ang pinakamalakas na squad para lang kumopya. Kumpletuhin muna ang pangunahing limang hero.'],
  ["Drone Chips at components","Magkakaibang item ang Drone Chips, Drone Components, at Drone Parts. Itugma ang chip set sa uri ng hero.","Apat na UR slots: Interference = Memory Ultra Fission; Defense = Gravitational Resonance Armor; Initial Move = Absolute Quantum Field; Attack = Lethal Firestorm. Gumawa ng unang UR set sa ganitong ayos. Mas maraming target ang tinatamaan ng Firestorm sa 2 at 5 stars.","Pantay na i-level ang isang buong core set. Tingnan ang role, hero type, star preview, at pangalan ng materyal sa upgrade screen.","Huwag ipagkamali ang Parts o Components sa Chips at huwag unahin ang second-squad set."],
  ['UR Gear at Blueprints','I-level 40 muna ang gintong Legendary gear ng pangunahing limang hero. Mas mabuti ang pokus kaysa manipis na paghahati.','Kimberly, DVA, Tesla: Railgun/Cannon bago Chip. Murphy, Williams, Lucius, Carlie: Armor bago Radar. Legendary Blueprints ang nagbubukas ng stars; Mythic Blueprints ay para sa kalaunan.','Tingnan ang requirement ng susunod na star at itapat ang malalaking upgrade sa aktibong scoring event kung sulit.','Nagbabago ang Blueprint need ayon sa star at version. Huwag maniwala sa fixed total o ikalat ang mamahaling materyal.'],
  ['Prayoridad sa pagbili sa shop','May sariling currency ang bawat shop. Bilhin ang nag-aalis ng bottleneck; hindi kailangang ubusin ng F2P ang stock.','VIP: weekly Stamina, piling speedups, at UR shards kapag kaya. Honor: pangunahing mag-ipon para sa Legendary Gear Blueprints. Alliance: laging magreserba ng 8h/24h shields para sa Sabadong patakaran ng RZSN, saka UR shards, Drone Parts, speedups. Campaign: resource boxes, lalo na gold malapit HQ30, Legendary Campaign chests, Drone Parts, o universal EW shards ayon sa stock.','Tingnan ang currency, stock, at reset bago bumili. Nag-iiba ang presyo at laman ayon sa server at version.','Huwag gastusin ang shield reserve sa convenience items. Walang eksaktong presyong ginagarantiya rito.'],
  ['Waterfall troop training','Panatilihin ang ilang Barracks sa mahahalagang level upang sunod-sunod na i-promote ang troops sa scoring window.','Milestones: T6 sa Barracks 17, T7 sa 20, T8 sa 24, T9 sa 27, T10 sa 30 plus Unit X. Sa 17/20/24/27, mag-train ng T6 sa linggo at i-promote T6 → T7 → T8 → T9 sa Biyernes kung binibigyan ng puntos ng live rules.','Suriin ang VS/event score, queues, oras, at Drill Ground capacity. Mag-iwan ng espasyo para sa buong chain.','Hindi laging apat na beses ang promotion score. Sundin ang aktibong event screen, hindi lumang calculator.'],
  ["General's Trial","Piliin ang pinakamataas na unlocked difficulty sa General's Trial. Maaaring masyadong malakas ang mga susunod na kalaban para sa solo, pero makakatulong ang alliance.","Kung masyadong malakas ang kalaban, humingi ng tulong sa alliance chat. Maaaring magsimula ng rally ang mas malalakas na RZSN member o sumali sa rally mo para talunin ito nang sama-sama. Sabihin ang difficulty at enemy level.","Tingnan ang mode, cost, attempts, rewards, at reset dahil may variants. Mag-coordinate sa chat; huwag asahang may R5 schedule bawat Trial.","Huwag bumaba sa mas madaling difficulty dahil lang may isang kalabang hindi mo kaya solo. Humingi muna ng rally support at tingnan ang kasalukuyang event rules."],
  ['Zombie Siege','Karaniwang 20 waves ang Zombie Siege. Hindi pinipigilan ng shield ang event zombies; Wall Defense at reinforcement ang mahalaga.','Maglagay ng tamang malakas na defense squad sa wall. Palakasin ng strong players ang weaker bases bago ang late waves; itanong sa R4/R5 ang event level.','Bantayan ang waves, wall squads, reinforcement capacity, at elimination. Kapag eliminated, hindi na aatakihin ang base sa run na iyon.','Nag-iiba ang failure rules ayon sa source at version. Huwag umasa sa “isang failure lang”; basahin ang live rules.'],
  ["Marshal's Guard",'Coordinated 30-minute damage event na may limang armored Tank bosses at karaniwang three-minute rallies.','Manatili malapit sa hive para maikli ang march. Ipadala ang pinakamalakas na angkop na squad; puwedeng weaker member ang magsimula para sa magandang join order. Mag-donate sa drill platform at sundin ang officers, hanggang limang phases bawat target set.','Tingnan ang live time at rally plan. Madalas 20:00 CET / 16:00 ST ang RZSN, pero ang kasalukuyang announcement ang masusunod.','Huwag gawing permanenteng oras ang nakasanayan o hatiin ang damage sa unplanned rallies.'],
  ['Batayan ng rally at combat','Magkaiba ang pagsusuri ng rally sa bawat mode. Mahalaga ang leader, buffs, counter, at target authorization.','Sa Season PvE na may infection, maaaring masakop ng resistance ng rally leader ang lower participants. Sa PvP, ihambing ang tunay na power, type counter, hero/gear buffs, at formation. Authorized leader lang ang magsisimula ng stronghold.','Bago mag-march, tingnan ang target, leader, join order, counter cycle, at buffs. Sa Sabado, panatilihin ang required shield at huwag umatake ng ally o unauthorized target.','Hindi kapalit ng PvP strength ang resistance. Nakakasama sa buong alliance ang maling leader o bumabang shield.'],
  ['Desert Storm','Manalo sa assigned groups, mabilis na komunikasyon, at tuloy-tuloy na puntos—hindi random solo teleport. Ang reserve ay ayon sa totoong availability.','Kung nasa map, unahin ang hospitals, saka hawakan ang refineries, Science Hub/Info Center, at Nuclear Silo kapag bukas. Mag-teleport nang staggered bilang grupo patungo sa tinawag na focus.','Kumpirmahin ang role, group, reserve status, at kasalukuyang objectives bago pumasok; maaaring mag-iba ang map at names.','Huwag mag-teleport mag-isa sa lane na walang suporta o humabol ng kills habang walang bantay ang structures.'],
  ['Alliance Tech at donation priority','Ang Alliance Research donations ay para sa alliance technology, hindi sa personal Tech Center. Sundin ang highlighted R4/R5 recommendation.','Gamitin ang 20% preferred tech bonus kapag active at mangolekta ng contribution points. Karaniwang Economy/Development sa simula; Combat ATK, DEF, HP para sa mature RZSN. Territory kung may nalalapit na pangangailangan lang.','Tingnan ang highlighted research, bonus, cost, at kasalukuyang officer call bago mag-donate.','Hindi sapilitan ang gold donation kapag kapos. Huwag ikalat sa hindi approved na branches.'],
  ['Minister / Capitol Buffs','Kunin ang title o buff bago pindutin ang Start. Karaniwang hindi nito pinaiikli ang nasimulang research o construction.','Humingi ng Secretary of Science bago ang mahabang research at Co-Builder bago construction. Kung may dalawang Tech Centers, ihanda ang parehong queues. Engineer skills ang Co-operative Research at Research Now na may sariling timer.','Tiyaking active ang title sa profile bago magsimula. Tingnan ang skill description at timer bago Research Now.','Huwag basta idagdag ang percentages o isipin na retroactive ang late title.']
]);

export const PRACTICAL_LABELS=Object.freeze(Object.fromEntries(Object.entries(LABELS).map(([lang,row])=>[
  lang,Object.freeze(Object.fromEntries(['overview','decision','check','caution','sources','related','squads','alliance','economy','front','back','type','job','shop','currency','priority'].map((key,index)=>[key,row[index]])))
])));

export const PRACTICAL_GUIDE_COPY=Object.freeze(Object.fromEntries(Object.entries(DATA).map(([lang,guides])=>[
  lang,Object.freeze(Object.fromEntries(Object.entries(guides).map(([id,copy])=>[id,Object.freeze(copy)])))
])));

export function practicalGuideCopy(lang,id){
  const copy=PRACTICAL_GUIDE_COPY[lang]?.[id];
  if(!copy) throw new Error(`Missing practical guide translation: ${lang}/${id}`);
  return copy;
}

export function practicalLabels(lang){
  const labels=PRACTICAL_LABELS[lang];
  if(!labels) throw new Error(`Missing practical guide labels: ${lang}`);
  return labels;
}

